// ============================================
// DataTable Component (from FormulaDisplay) - Enhanced with vibrant colors
// ============================================

// Color themes for different table types
const tableColorThemes = [
    { header: 'linear-gradient(135deg, #7c3aed 0%, #8b5cf6 100%)', evenRow: 'rgba(139, 92, 246, 0.03)', oddRow: 'rgba(139, 92, 246, 0.08)', border: '#8b5cf6', accent: '#7c3aed' },
    { header: 'linear-gradient(135deg, #0891b2 0%, #06b6d4 100%)', evenRow: 'rgba(6, 182, 212, 0.03)', oddRow: 'rgba(6, 182, 212, 0.08)', border: '#06b6d4', accent: '#0891b2' },
    { header: 'linear-gradient(135deg, #059669 0%, #10b981 100%)', evenRow: 'rgba(16, 185, 129, 0.03)', oddRow: 'rgba(16, 185, 129, 0.08)', border: '#10b981', accent: '#059669' },
    { header: 'linear-gradient(135deg, #db2777 0%, #ec4899 100%)', evenRow: 'rgba(236, 72, 153, 0.03)', oddRow: 'rgba(236, 72, 153, 0.08)', border: '#ec4899', accent: '#db2777' },
    { header: 'linear-gradient(135deg, #ea580c 0%, #f97316 100%)', evenRow: 'rgba(249, 115, 22, 0.03)', oddRow: 'rgba(249, 115, 22, 0.08)', border: '#f97316', accent: '#ea580c' },
];

let tableColorIndex = 0;
const getNextTableTheme = () => {
    const theme = tableColorThemes[tableColorIndex % tableColorThemes.length];
    tableColorIndex++;
    return theme;
};

function DataTable({
    headers,
    rows,
    colorTheme
}: {
    headers: string[];
    rows: (string | number | React.ReactNode | undefined)[][];
    colorTheme?: { header: string; evenRow: string; oddRow: string; border: string; accent: string };
}) {
    const theme = colorTheme || getNextTableTheme();

    return (
        <div style={{
            overflowX: 'auto',
            borderRadius: '12px',
            border: `2px solid ${theme.border}`,
            boxShadow: `0 4px 16px rgba(0, 0, 0, 0.08), 0 0 0 1px ${theme.border}20`,
            background: 'white',
        }}>
            <table style={{
                width: '100%',
                borderCollapse: 'collapse',
                fontSize: '0.82rem',
            }}>
                <thead>
                    <tr style={{ background: theme.header }}>
                        {headers.map((header, i) => (
                            <th key={i} style={{
                                padding: '0.875rem 1rem',
                                textAlign: 'left',
                                fontWeight: '700',
                                color: 'white',
                                borderBottom: 'none',
                                whiteSpace: 'nowrap',
                                textTransform: 'uppercase',
                                fontSize: '0.72rem',
                                letterSpacing: '0.05em',
                                textShadow: '0 1px 2px rgba(0,0,0,0.1)',
                            }}>
                                <span style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                                    {i === 0 && <span style={{ opacity: 0.8 }}>📋</span>}
                                    {header}
                                </span>
                            </th>
                        ))}
                    </tr>
                </thead>
                <tbody>
                    {rows.length === 0 ? (
                        <tr>
                            <td
                                colSpan={headers.length}
                                style={{
                                    padding: '2.5rem',
                                    textAlign: 'center',
                                    color: '#9ca3af',
                                    background: 'linear-gradient(180deg, rgba(249, 250, 251, 0) 0%, rgba(249, 250, 251, 1) 100%)',
                                }}
                            >
                                <span style={{ fontSize: '1.5rem', marginBottom: '8px', display: 'block' }}>📭</span>
                                No data available
                            </td>
                        </tr>
                    ) : (
                        rows.map((row, rowIndex) => (
                            <tr
                                key={rowIndex}
                                style={{
                                    background: rowIndex % 2 === 0 ? theme.evenRow : theme.oddRow,
                                    transition: 'all 0.2s ease',
                                    borderLeft: rowIndex % 2 === 1 ? `3px solid ${theme.border}40` : '3px solid transparent',
                                }}
                                onMouseEnter={(e) => {
                                    e.currentTarget.style.background = `${theme.border}15`;
                                    e.currentTarget.style.transform = 'scale(1.002)';
                                }}
                                onMouseLeave={(e) => {
                                    e.currentTarget.style.background = rowIndex % 2 === 0 ? theme.evenRow : theme.oddRow;
                                    e.currentTarget.style.transform = 'scale(1)';
                                }}
                            >
                                {row.map((cell, cellIndex) => (
                                    <td key={cellIndex} style={{
                                        padding: '0.75rem 1rem',
                                        borderBottom: `1px solid ${theme.border}20`,
                                        color: '#374151',
                                        fontWeight: cellIndex === 0 ? '600' : '400',
                                    }}>
                                        {cellIndex === 0 && typeof cell === 'number' ? (
                                            <span style={{
                                                display: 'inline-flex',
                                                alignItems: 'center',
                                                justifyContent: 'center',
                                                width: '24px',
                                                height: '24px',
                                                borderRadius: '6px',
                                                background: theme.header,
                                                color: 'white',
                                                fontSize: '0.7rem',
                                                fontWeight: '700',
                                            }}>
                                                {cell}
                                            </span>
                                        ) : cellIndex === 1 ? (
                                            <span style={{
                                                fontFamily: 'monospace',
                                                padding: '2px 8px',
                                                background: `${theme.border}15`,
                                                borderRadius: '4px',
                                                color: theme.accent,
                                                fontWeight: '600',
                                            }}>
                                                {cell ?? 'N/A'}
                                            </span>
                                        ) : (
                                            cell ?? <span style={{ color: '#d1d5db', fontStyle: 'italic' }}>N/A</span>
                                        )}
                                    </td>
                                ))}
                            </tr>
                        ))
                    )}
                </tbody>
            </table>
        </div>
    );
}

// Color scheme for different manufacturers - Enhanced with more visible pastel tints
const getManufacturerColor = (manufacturer: string): { primary: string; light: string; border: string; glow: string; glass: string } => {
    const mfr = manufacturer?.toLowerCase() || '';

    if (mfr.includes('indiana')) {
        return {
            primary: '#f97316',
            light: 'rgba(249, 115, 22, 0.18)',
            border: 'rgba(249, 115, 22, 0.4)',
            glow: 'rgba(249, 115, 22, 0.12)',
            glass: 'linear-gradient(135deg, rgba(255, 237, 213, 0.6) 0%, rgba(254, 215, 170, 0.4) 50%, rgba(251, 191, 36, 0.15) 100%)'
        };
    }
    if (mfr.includes('zenex')) {
        return {
            primary: '#ec4899',
            light: 'rgba(236, 72, 153, 0.18)',
            border: 'rgba(236, 72, 153, 0.4)',
            glow: 'rgba(236, 72, 153, 0.12)',
            glass: 'linear-gradient(135deg, rgba(253, 242, 248, 0.7) 0%, rgba(252, 231, 243, 0.5) 50%, rgba(244, 114, 182, 0.15) 100%)'
        };
    }
    if (mfr.includes('ajanta')) {
        return {
            primary: '#3b82f6',
            light: 'rgba(59, 130, 246, 0.18)',
            border: 'rgba(59, 130, 246, 0.4)',
            glow: 'rgba(59, 130, 246, 0.12)',
            glass: 'linear-gradient(135deg, rgba(239, 246, 255, 0.7) 0%, rgba(219, 234, 254, 0.5) 50%, rgba(147, 197, 253, 0.2) 100%)'
        };
    }
    if (mfr.includes('cadila')) {
        return {
            primary: '#14b8a6',
            light: 'rgba(20, 184, 166, 0.18)',
            border: 'rgba(20, 184, 166, 0.4)',
            glow: 'rgba(20, 184, 166, 0.12)',
            glass: 'linear-gradient(135deg, rgba(240, 253, 250, 0.7) 0%, rgba(204, 251, 241, 0.5) 50%, rgba(94, 234, 212, 0.2) 100%)'
        };
    }
    // Default purple
    return {
        primary: '#8b5cf6',
        light: 'rgba(139, 92, 246, 0.18)',
        border: 'rgba(139, 92, 246, 0.4)',
        glow: 'rgba(139, 92, 246, 0.12)',
        glass: 'linear-gradient(135deg, rgba(245, 243, 255, 0.7) 0%, rgba(237, 233, 254, 0.5) 50%, rgba(196, 181, 253, 0.2) 100%)'
    };
};

// ============================================
// Batch Status Capsule Component - Shows RM data matching status
// Green: Batches with RM requisition data. Red: Batches without RM data
// ============================================
interface BatchStatusCapsuleProps {
    matched: number;
    unmatched: number;
    onGreenClick?: () => void | Promise<void>;
    onRedClick?: () => void | Promise<void>;
    size?: 'small' | 'medium' | 'large';
    type: 'RM' | 'PPM' | 'PM' | 'RM COA' | 'PM COA' | 'PPM COA' | 'Bulk COA' | 'Finish COA';
    /** When set, the row fills available width (aligned stacked columns in MFC headers). */
    stretch?: boolean;
}

function BatchStatusCapsule({ matched, unmatched, onGreenClick, onRedClick, size = 'medium', type, stretch }: BatchStatusCapsuleProps) {
    const total = matched + unmatched;
    if (total === 0) return null;

    // Size configurations
    const sizeConfig = {
        // Keep "small" consistent with MiniArStatusCapsule (20px)
        small: { height: '20px', fontSize: '10px', padding: '2px 8px', minWidth: '60px' },
        medium: { height: '26px', fontSize: '11px', padding: '4px 8px', minWidth: '80px' },
        large: { height: '32px', fontSize: '12px', padding: '5px 12px', minWidth: '100px' }
    };
    const config = sizeConfig[size];
    const hasGreen = matched > 0;
    const hasRed = unmatched > 0;
    // When both sides exist, keep them equal width (prevents tiny red sliver).
    const greenFlex = hasGreen && hasRed ? 1 : 1;
    const redFlex = hasGreen && hasRed ? 1 : 1;

    return (
        <div
            style={{
                display: stretch ? 'flex' : 'inline-flex',
                width: stretch ? '100%' : undefined,
                alignItems: 'center',
                gap: '4px',
                flexDirection: 'row' as const,
            }}
            title={`${type === 'RM COA' ? 'RM COA' : type} Data: ${matched} found, ${unmatched} missing`}
        >
            {/* Type Label — green tint only (capsules use green + red only) */}
            <span style={{
                fontSize: size === 'small' ? '9px' : '10px',
                fontWeight: 700,
                color: '#059669',
                background: '#ecfdf5',
                padding: size === 'small' ? '2px 5px' : '3px 6px',
                borderRadius: '4px',
                textTransform: (type === 'RM COA' || type === 'PM COA' || type === 'PPM COA' || type === 'Bulk COA' || type === 'Finish COA') ? 'none' : 'uppercase',
                letterSpacing: '0.5px',
                width: size === 'small' ? '56px' : undefined,
                minWidth: size === 'small' ? '56px' : undefined,
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
            }}>
                {type}
            </span>
            {/* Capsule */}
            <div
                style={{
                    display: 'inline-flex',
                    alignItems: 'stretch',
                    flex: stretch ? 1 : undefined,
                    minWidth: stretch ? 0 : config.minWidth,
                    width: stretch ? '100%' : undefined,
                    height: config.height,
                    borderRadius: '20px',
                    overflow: 'hidden',
                    boxShadow: '0 2px 6px rgba(0,0,0,0.15), inset 0 1px 0 rgba(255,255,255,0.2)',
                    border: '1px solid rgba(255,255,255,0.3)',
                }}
            >
                {/* Green Section - RM Data Found */}
                {hasGreen && (
                    <button
                        onClick={(e) => { e.stopPropagation(); onGreenClick?.(); }}
                        style={{
                            flex: greenFlex,
                            minWidth: size === 'small' ? '44px' : '40px',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            gap: '3px',
                            padding: config.padding,
                            background: 'linear-gradient(135deg, #059669 0%, #10b981 100%)',
                            border: 'none',
                            cursor: onGreenClick ? 'pointer' : 'default',
                            color: 'white',
                            fontSize: config.fontSize,
                            fontWeight: 700,
                            transition: 'all 0.2s ease',
                            whiteSpace: 'nowrap',
                        }}
                        onMouseEnter={(e) => { if (onGreenClick) e.currentTarget.style.filter = 'brightness(1.1)'; }}
                        onMouseLeave={(e) => { e.currentTarget.style.filter = 'brightness(1)'; }}
                        title={`${matched} batches with ${type} requisition data - Click to view`}
                    >
                        <span style={{ fontSize: '0.85em' }}>✓</span>
                        {matched}
                    </button>
                )}
                {/* Red Section - RM Data Missing */}
                {hasRed && (
                    <button
                        onClick={(e) => { e.stopPropagation(); onRedClick?.(); }}
                        style={{
                            flex: redFlex,
                            minWidth: size === 'small' ? '44px' : '40px',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            gap: '3px',
                            padding: config.padding,
                            background: 'linear-gradient(135deg, #dc2626 0%, #ef4444 100%)',
                            border: 'none',
                            cursor: onRedClick ? 'pointer' : 'default',
                            color: 'white',
                            fontSize: config.fontSize,
                            fontWeight: 700,
                            transition: 'all 0.2s ease',
                            whiteSpace: 'nowrap',
                        }}
                        onMouseEnter={(e) => { if (onRedClick) e.currentTarget.style.filter = 'brightness(1.1)'; }}
                        onMouseLeave={(e) => { e.currentTarget.style.filter = 'brightness(1)'; }}
                        title={`${unmatched} batches without ${type} requisition data - Click to view`}
                    >
                        <span style={{ fontSize: '0.85em' }}>✗</span>
                        {unmatched}
                    </button>
                )}
            </div>
        </div>
    );
}

// ============================================
// Mini AR Status Capsule (AR Numbers)
// ============================================
interface MiniArStatusCapsuleProps {
    label: string;
    found: number;
    missing: number;
    accent: 'rm' | 'ppm' | 'pm';
    onFoundClick?: () => void;
    onMissingClick?: () => void;
    stretch?: boolean;
}

function MiniArStatusCapsule({ label, found, missing, accent: _accent, onFoundClick, onMissingClick, stretch }: MiniArStatusCapsuleProps) {
    const total = found + missing;
    if (total === 0) return null;

    const accentStyles = {
        labelColor: '#059669',
        labelBg: '#ecfdf5',
        foundBg: 'linear-gradient(135deg, #059669 0%, #10b981 100%)',
    };
    const hasGreen = found > 0;
    const hasRed = missing > 0;
    const greenFlex = hasGreen && hasRed ? 1 : 1;
    const redFlex = hasGreen && hasRed ? 1 : 1;

    return (
        <div
            style={{
                display: stretch ? 'flex' : 'inline-flex',
                width: stretch ? '100%' : undefined,
                alignItems: 'center',
                gap: '4px',
                flexDirection: 'row' as const,
            }}
            title={`${label}: ${found} found, ${missing} missing`}
        >
            <span style={{
                fontSize: '9px',
                fontWeight: 700,
                color: accentStyles.labelColor,
                background: accentStyles.labelBg,
                padding: '2px 5px',
                borderRadius: '4px',
                letterSpacing: '0.5px',
                textTransform: 'uppercase',
                width: '56px',
                minWidth: '56px',
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
            }}>
                {label}
            </span>
            <div
                style={{
                    display: 'inline-flex',
                    alignItems: 'stretch',
                    flex: stretch ? 1 : undefined,
                    minWidth: stretch ? 0 : '80px',
                    width: stretch ? '100%' : undefined,
                    height: '20px',
                    borderRadius: '20px',
                    overflow: 'hidden',
                    boxShadow: '0 2px 6px rgba(0,0,0,0.15), inset 0 1px 0 rgba(255,255,255,0.2)',
                    border: '1px solid rgba(255,255,255,0.3)',
                }}
            >
                {hasGreen && (
                    <button
                        onClick={(e) => { e.stopPropagation(); onFoundClick?.(); }}
                        style={{
                        flex: greenFlex,
                        minWidth: '44px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        gap: '3px',
                        padding: '2px 8px',
                        background: accentStyles.foundBg,
                        color: 'white',
                        fontSize: '10px',
                        fontWeight: 700,
                        whiteSpace: 'nowrap',
                        border: 'none',
                        cursor: onFoundClick ? 'pointer' : 'default',
                    }}
                        title={`${found} ${label} found${onFoundClick ? ' - Click to view' : ''}`}
                    >
                        <span style={{ fontSize: '0.85em' }}>✓</span>
                        {found}
                    </button>
                )}
                {hasRed && (
                    <button
                        onClick={(e) => { e.stopPropagation(); onMissingClick?.(); }}
                        style={{
                        flex: redFlex,
                        minWidth: '44px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        gap: '3px',
                        padding: '2px 8px',
                        background: 'linear-gradient(135deg, #dc2626 0%, #ef4444 100%)',
                        color: 'white',
                        fontSize: '10px',
                        fontWeight: 700,
                        whiteSpace: 'nowrap',
                        border: 'none',
                        cursor: onMissingClick ? 'pointer' : 'default',
                    }}
                        title={`${missing} ${label} missing${onMissingClick ? ' - Click to view' : ''}`}
                    >
                        <span style={{ fontSize: '0.85em' }}>✗</span>
                        {missing}
                    </button>
                )}
            </div>
        </div>
    );
}

// ============================================
// Product Master Capsule (4-section)
// ============================================
interface ProductMasterCapsuleProps {
    stats: { found: number; missingFromPM: number; withErrors: number; ok: number } | null;
    onFoundClick?: () => void;
    onMissingClick?: () => void;
    onErrorsClick?: () => void;
    onOkClick?: () => void;
}

function ProductMasterCapsule({ stats, onFoundClick, onMissingClick, onErrorsClick, onOkClick }: ProductMasterCapsuleProps) {
    if (!stats) return null;
    const total = stats.found + stats.missingFromPM;
    if (total === 0) return null;

    const btnStyle = (bg: string, borderRadius?: string): React.CSSProperties => ({
        display: 'flex',
        alignItems: 'center',
        gap: '3px',
        background: bg,
        color: 'white',
        padding: '3px 8px',
        fontSize: '0.72rem',
        fontWeight: 700,
        whiteSpace: 'nowrap',
        border: 'none',
        cursor: 'pointer',
        borderRadius: borderRadius ?? '0',
    });

    return (
        <div style={{ display: 'flex', alignItems: 'center', flexShrink: 0, borderRadius: '20px', overflow: 'hidden', border: '1px solid #c4b5fd', boxShadow: '0 1px 3px rgba(99,102,241,0.15)' }}>
            <div style={{ background: 'linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%)', color: 'white', padding: '3px 10px', fontSize: '0.7rem', fontWeight: 700, whiteSpace: 'nowrap', borderRadius: '20px 0 0 20px' }}>
                Product Master
            </div>
            <button onClick={(e) => { e.stopPropagation(); onFoundClick?.(); }} style={btnStyle('#059669')} title={`${stats.found} product codes found in both Formula Master & Product Master`}>
                <span>✓</span><span>{stats.found}</span>
            </button>
            <button onClick={(e) => { e.stopPropagation(); onMissingClick?.(); }} style={btnStyle('#dc2626')} title={`${stats.missingFromPM} product codes in Formula Master but NOT in Product Master`}>
                <span>✗</span><span>{stats.missingFromPM}</span>
            </button>
            <button onClick={(e) => { e.stopPropagation(); onErrorsClick?.(); }} style={btnStyle('#f59e0b')} title={`${stats.withErrors} product codes found in Product Master but with field errors or mismatches`}>
                <span>⚠</span><span>{stats.withErrors}</span>
            </button>
            <button onClick={(e) => { e.stopPropagation(); onOkClick?.(); }} style={btnStyle('#10b981', '0 20px 20px 0')} title={`${stats.ok} product codes found in Product Master with no errors`}>
                <span>✓OK</span><span>{stats.ok}</span>
            </button>
        </div>
    );
}

// ============================================
// Product Master Cross-Reference Modal
// ============================================
interface ProductMasterCrossRefModalProps {
    show: boolean;
    onClose: () => void;
    type: 'found' | 'missing' | 'errors' | 'ok';
    sectionName: string;
    items: { productCode: string; productName: string; masterCardNo: string; missingFields: string[]; mismatchFields: string[] }[];
    search: string;
    onSearchChange: (v: string) => void;
}

function ProductMasterCrossRefModal({ show, onClose, type, sectionName, items, search, onSearchChange }: ProductMasterCrossRefModalProps) {
    if (!show) return null;

    const typeConfig = {
        found:   { label: 'Found in Product Master',               color: '#059669', bg: '#ecfdf5', border: '#a7f3d0', icon: '✓' },
        missing: { label: 'Missing from Product Master',           color: '#dc2626', bg: '#fef2f2', border: '#fecaca', icon: '✗' },
        errors:  { label: 'Found with Errors in Product Master',   color: '#d97706', bg: '#fffbeb', border: '#fde68a', icon: '⚠' },
        ok:      { label: 'Found — No Errors in Product Master',   color: '#059669', bg: '#ecfdf5', border: '#a7f3d0', icon: '✓OK' },
    }[type];

    const q = search.trim().toLowerCase();
    const filtered = q
        ? items.filter(i =>
            i.productCode.toLowerCase().includes(q) ||
            i.productName.toLowerCase().includes(q) ||
            i.masterCardNo.toLowerCase().includes(q)
          )
        : items;

    const showErrors = type === 'errors';

    return (
        <>
            {/* Backdrop */}
            <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.35)', zIndex: 1100 }} />
            {/* Modal */}
            <div style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%,-50%)', zIndex: 1101, width: '92%', maxWidth: '900px', maxHeight: '88vh', display: 'flex', flexDirection: 'column', background: 'white', borderRadius: '16px', boxShadow: '0 25px 50px rgba(0,0,0,0.25)', overflow: 'hidden' }}>
                {/* Header */}
                <div style={{ background: `linear-gradient(135deg, ${typeConfig.color} 0%, ${typeConfig.color}cc 100%)`, padding: '16px 24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexShrink: 0 }}>
                    <div>
                        <div style={{ color: 'white', fontWeight: 700, fontSize: '1rem' }}>
                            {typeConfig.icon} {typeConfig.label}
                        </div>
                        <div style={{ color: 'rgba(255,255,255,0.8)', fontSize: '0.8rem', marginTop: '2px' }}>
                            {sectionName} · {filtered.length} product code{filtered.length !== 1 ? 's' : ''}
                        </div>
                    </div>
                    <button onClick={onClose} style={{ background: 'rgba(255,255,255,0.2)', border: 'none', borderRadius: '8px', color: 'white', padding: '6px 12px', cursor: 'pointer', fontSize: '0.85rem', fontWeight: 600 }}>✕ Close</button>
                </div>
                {/* Search */}
                <div style={{ padding: '12px 24px', borderBottom: '1px solid #e5e7eb', flexShrink: 0 }}>
                    <input
                        type="text"
                        placeholder="Search by product code, name, or MFC..."
                        value={search}
                        onChange={e => onSearchChange(e.target.value)}
                        style={{ width: '100%', padding: '8px 12px', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.875rem', outline: 'none', boxSizing: 'border-box' }}
                    />
                </div>
                {/* Table */}
                <div style={{ overflowY: 'auto', flex: 1 }}>
                    {filtered.length === 0 ? (
                        <div style={{ textAlign: 'center', padding: '3rem', color: '#9ca3af' }}>No records found</div>
                    ) : (
                        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.82rem' }}>
                            <thead style={{ position: 'sticky', top: 0, background: '#f9fafb', zIndex: 1 }}>
                                <tr style={{ borderBottom: '2px solid #e5e7eb' }}>
                                    <th style={{ padding: '10px 12px', textAlign: 'left', color: '#6b7280', fontWeight: 600, width: '40px' }}>#</th>
                                    <th style={{ padding: '10px 12px', textAlign: 'left', color: '#6b7280', fontWeight: 600 }}>Product Code</th>
                                    <th style={{ padding: '10px 12px', textAlign: 'left', color: '#6b7280', fontWeight: 600 }}>Product Name</th>
                                    <th style={{ padding: '10px 12px', textAlign: 'left', color: '#6b7280', fontWeight: 600 }}>MFC No</th>
                                    {showErrors && <th style={{ padding: '10px 12px', textAlign: 'left', color: '#6b7280', fontWeight: 600 }}>Errors</th>}
                                    {type === 'missing' && <th style={{ padding: '10px 12px', textAlign: 'left', color: '#6b7280', fontWeight: 600 }}>Status</th>}
                                </tr>
                            </thead>
                            <tbody>
                                {filtered.map((item, i) => (
                                    <tr key={item.productCode} style={{ borderBottom: '1px solid #f3f4f6', background: i % 2 === 0 ? 'white' : '#fafafa' }}>
                                        <td style={{ padding: '8px 12px', color: '#9ca3af', fontWeight: 600 }}>{i + 1}</td>
                                        <td style={{ padding: '8px 12px', fontFamily: 'monospace', fontWeight: 700, color: '#1f2937' }}>{item.productCode}</td>
                                        <td style={{ padding: '8px 12px', color: '#374151', maxWidth: '240px' }}>{item.productName || <span style={{ color: '#9ca3af', fontStyle: 'italic' }}>—</span>}</td>
                                        <td style={{ padding: '8px 12px', fontFamily: 'monospace', color: '#6b7280' }}>{item.masterCardNo || <span style={{ color: '#9ca3af', fontStyle: 'italic' }}>—</span>}</td>
                                        {showErrors && (
                                            <td style={{ padding: '8px 12px' }}>
                                                <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px' }}>
                                                    {item.missingFields.map(f => (
                                                        <span key={f} style={{ background: '#fee2e2', color: '#dc2626', padding: '1px 6px', borderRadius: '6px', fontSize: '0.72rem', fontWeight: 600 }}>Missing: {f}</span>
                                                    ))}
                                                    {item.mismatchFields.map(f => (
                                                        <span key={f} style={{ background: '#fef3c7', color: '#d97706', padding: '1px 6px', borderRadius: '6px', fontSize: '0.72rem', fontWeight: 600 }}>Mismatch: {f}</span>
                                                    ))}
                                                </div>
                                            </td>
                                        )}
                                        {type === 'missing' && (
                                            <td style={{ padding: '8px 12px' }}>
                                                <span style={{ background: '#fee2e2', color: '#dc2626', padding: '2px 8px', borderRadius: '8px', fontSize: '0.72rem', fontWeight: 700 }}>Not in Product Master</span>
                                            </td>
                                        )}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    )}
                </div>
            </div>
        </>
    );
}

// APQR Preview Modal Component
// ============================================
interface APQRPreviewModalProps {
    isOpen: boolean;
    onClose: () => void;
    data: any;
    isLoading: boolean;
    onGenerate: () => void;
    productCode: string;
    year: string;
}

function APQRPreviewModal({ isOpen, onClose, data, isLoading, onGenerate, productCode, year }: APQRPreviewModalProps) {
    if (!isOpen) return null;

    return (
        <div style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0, 0, 0, 0.7)',
            zIndex: 9999,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '2rem',
        }}>
            <div style={{
                background: 'white',
                borderRadius: '24px',
                width: '100%',
                maxWidth: '800px',
                maxHeight: '90vh',
                overflow: 'hidden',
                boxShadow: '0 20px 50px rgba(0,0,0,0.3)',
                display: 'flex',
                flexDirection: 'column',
                animation: 'slideUp 0.3s ease-out',
            }}>
                {/* Header */}
                <div style={{
                    padding: '1.5rem 2rem',
                    borderBottom: '1px solid #e5e7eb',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    background: 'linear-gradient(to right, #f9fafb, white)',
                }}>
                    <div>
                        <h2 style={{ fontSize: '1.5rem', fontWeight: '800', color: '#111827', margin: 0 }}>
                            APQR Generation Preview
                        </h2>
                        <p style={{ color: '#6b7280', marginTop: '4px', fontSize: '0.9rem' }}>
                            Product: <span style={{ fontWeight: '600', color: '#3b82f6' }}>{productCode}</span> | Year: <span style={{ fontWeight: '600' }}>{year}</span>
                        </p>
                    </div>
                    <button onClick={onClose} style={{
                        background: 'none', border: 'none', fontSize: '1.5rem', cursor: 'pointer', color: '#9ca3af',
                    }}>×</button>
                </div>

                {/* Content */}
                <div style={{ flex: 1, overflowY: 'auto', padding: '2rem' }}>
                    {isLoading ? (
                        <div style={{ textAlign: 'center', padding: '4rem' }}>
                            <div style={{
                                width: '40px', height: '40px', border: '3px solid #e5e7eb',
                                borderTopColor: '#3b82f6', borderRadius: '50%', margin: '0 auto 1rem',
                                animation: 'spin 1s linear infinite'
                            }} />
                            <p style={{ color: '#6b7280' }}>Loading APQR data...</p>
                        </div>
                    ) : data ? (
                        <div style={{ display: 'grid', gap: '2rem' }}>
                            {/* Stats Cards */}
                            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '1rem' }}>
                                <div style={{ background: '#eff6ff', padding: '1.5rem', borderRadius: '12px', border: '1px solid #dbeafe' }}>
                                    <h3 style={{ fontSize: '0.875rem', color: '#1e40af', marginBottom: '0.5rem' }}>Total Batches</h3>
                                    <p style={{ fontSize: '2rem', fontWeight: '800', color: '#1e3a8a', margin: 0 }}>{data.totalBatches}</p>
                                </div>
                                <div style={{ background: '#f0fdf4', padding: '1.5rem', borderRadius: '12px', border: '1px solid #dcfce7' }}>
                                    <h3 style={{ fontSize: '0.875rem', color: '#166534', marginBottom: '0.5rem' }}>Avg Batch Size</h3>
                                    <p style={{ fontSize: '2rem', fontWeight: '800', color: '#14532d', margin: 0 }}>{data.avgBatchSize}</p>
                                </div>
                                <div style={{ background: '#fef2f2', padding: '1.5rem', borderRadius: '12px', border: '1px solid #fee2e2' }}>
                                    <h3 style={{ fontSize: '0.875rem', color: '#991b1b', marginBottom: '0.5rem' }}>Review Period</h3>
                                    <p style={{ fontSize: '1.1rem', fontWeight: '700', color: '#7f1d1d', margin: '0.5rem 0 0' }}>{data.reviewPeriod}</p>
                                </div>
                            </div>

                            {/* Batch List Preview */}
                            <div>
                                <h3 style={{ fontSize: '1.1rem', fontWeight: '700', marginBottom: '1rem', color: '#374151' }}>
                                    Batch Data Preview ({data.batches?.length || 0})
                                </h3>
                                <div style={{ border: '1px solid #e5e7eb', borderRadius: '8px', overflow: 'hidden' }}>
                                    <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.875rem' }}>
                                        <thead style={{ background: '#f9fafb', borderBottom: '1px solid #e5e7eb' }}>
                                            <tr>
                                                <th style={{ padding: '0.75rem 1rem', textAlign: 'left', fontWeight: '600', color: '#4b5563' }}>Batch No</th>
                                                <th style={{ padding: '0.75rem 1rem', textAlign: 'left', fontWeight: '600', color: '#4b5563' }}>Mfg Date</th>
                                                <th style={{ padding: '0.75rem 1rem', textAlign: 'left', fontWeight: '600', color: '#4b5563' }}>Exp Date</th>
                                                <th style={{ padding: '0.75rem 1rem', textAlign: 'left', fontWeight: '600', color: '#4b5563' }}>Size</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {data.batches?.slice(0, 5).map((b: any, i: number) => (
                                                <tr key={i} style={{ borderBottom: '1px solid #f3f4f6' }}>
                                                    <td style={{ padding: '0.75rem 1rem', color: '#111827', fontWeight: '500' }}>{b.batch_number}</td>
                                                    <td style={{ padding: '0.75rem 1rem', color: '#4b5563' }}>{b.mfg_date}</td>
                                                    <td style={{ padding: '0.75rem 1rem', color: '#4b5563' }}>{b.exp_date}</td>
                                                    <td style={{ padding: '0.75rem 1rem', color: '#4b5563' }}>{b.batch_size}</td>
                                                </tr>
                                            ))}
                                            {data.batches?.length > 5 && (
                                                <tr>
                                                    <td colSpan={4} style={{ padding: '0.75rem 1rem', textAlign: 'center', color: '#6b7280', fontStyle: 'italic', background: '#f9fafb' }}>
                                                        ...and {data.batches.length - 5} more batches
                                                    </td>
                                                </tr>
                                            )}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div style={{ textAlign: 'center', padding: '4rem', color: '#ef4444' }}>
                            Failed to load preview data.
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div style={{
                    padding: '1.5rem 2rem',
                    borderTop: '1px solid #e5e7eb',
                    display: 'flex',
                    justifyContent: 'flex-end',
                    gap: '1rem',
                    background: '#f9fafb',
                }}>
                    <button
                        onClick={onClose}
                        style={{
                            padding: '0.75rem 1.5rem',
                            borderRadius: '8px',
                            border: '1px solid #d1d5db',
                            background: 'white',
                            color: '#374151',
                            fontWeight: '600',
                            cursor: 'pointer',
                        }}
                    >
                        Cancel
                    </button>
                    <button
                        onClick={onGenerate}
                        disabled={isLoading || !data}
                        style={{
                            padding: '0.75rem 1.5rem',
                            borderRadius: '8px',
                            background: 'linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)',
                            color: 'white',
                            fontWeight: '600',
                            border: 'none',
                            cursor: isLoading || !data ? 'not-allowed' : 'pointer',
                            opacity: isLoading || !data ? 0.7 : 1,
                            boxShadow: '0 4px 6px rgba(37, 99, 235, 0.2)',
                        }}
                    >
                        {isLoading ? 'Generating...' : 'Download DOCX'}
                    </button>
                </div>
            </div>
        </div>
    );
}

