    const generateApqr = async () => {
        if (!selectedMfc) return;
        setApqrLoading(true);
        setApqrError(null);
        try {
            const res = await fetch('/api/apqr/generate', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    productCode: selectedMfc.masterFormulaDetails.productCode,
                    year: selectedYear
                })
            });

            if (!res.ok) {
                const errorData = await res.json();
                throw new Error(errorData.error || 'Failed to generate APQR');
            }

            const arrayBuffer = await res.arrayBuffer();
            const blob = new Blob([arrayBuffer], { type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `APQR_${selectedMfc.masterFormulaDetails.productCode}_${selectedYear}.docx`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            window.URL.revokeObjectURL(url);

            alert(`✅ APQR generated successfully!\n\nFile saved to: files/doc/\nFile downloaded to your Downloads folder.`);
            setApqrModalOpen(false);
        } catch (err: any) {
            setApqrError(err.message || 'Failed to generate APQR');
            console.error('Error generating APQR:', err);
        } finally {
            setApqrLoading(false);
        }
    };

    const handleExportToExcel = (data: any[], fileName: string) => {
        const asText = (v: any) => {
            const s = (v ?? '').toString();
            // Prefix with apostrophe so Excel preserves tokens (no scientific notation / trimming).
            return s ? `'${s}` : '';
        };

        const exportData = data.map((item, index) => {
            const batchNumber = item.batchNumber ?? item.batchNo ?? item.batch ?? '';
            const arNumber = item.arNo ?? item.arNumber ?? item.arToken ?? item.ar ?? '';

            const row: Record<string, any> = {
                'SR No.': index + 1,
                'AR Number': asText(arNumber),
                'Material/Item Code': asText(item.materialCode ?? item.itemCode ?? item.productCode ?? ''),
                'Material/Item Name': item.materialName ?? item.itemName ?? item.productName ?? '',
                'Batch Number': asText(batchNumber),
            };

            // If richer RM/PM/PPM COA structures are provided, include them as additional columns.
            const maybeMfc = item.mfcNo ?? item.mfc ?? item.formulaMfc ?? '';
            const productName = item.productName ?? item.itemName ?? item.materialName ?? '';
            const batchSize = item.batchSize ?? '';
            const mfgDate = item.mfgDate ?? '';
            const expiryDate = item.expiryDate ?? item.expiry ?? '';
            const department = item.department ?? item.dept ?? '';
            const make = item.make ?? '';

            if (maybeMfc) row['MFC No'] = asText(maybeMfc);
            if (productName && !row['Material/Item Name']) row['Material/Item Name'] = productName;
            if (batchSize) row['Batch Size'] = batchSize;
            if (mfgDate) row['MFG Date'] = mfgDate;
            if (expiryDate) row['Expiry Date'] = expiryDate;
            if (department) row['Dept'] = department;
            if (make) row['Make'] = make;

            // Flatten common nested structures if present.
            if (Array.isArray(item.batches) && item.batches.length > 0) {
                row['Batches (all)'] = item.batches.map((b: any) => (b ?? '').toString()).filter(Boolean).join(', ');
                row['Batch Count'] = item.batches.length;
            }
            if (Array.isArray(item.items) && item.items.length > 0) {
                row['Lines'] = item.items.length;
                const mats = Array.from(
                    new Set(item.items.map((it: any) => (it?.materialCode ?? '').toString().trim()).filter(Boolean))
                );
                const matNames = Array.from(
                    new Set(item.items.map((it: any) => (it?.materialName ?? '').toString().trim()).filter(Boolean))
                );
                const reqNos = Array.from(
                    new Set(item.items.map((it: any) => (it?.matReqNo ?? '').toString().trim()).filter(Boolean))
                );
                if (mats.length) row['Material Codes'] = mats.join(', ');
                if (matNames.length) row['Material Names'] = matNames.join(', ');
                if (reqNos.length) row['Req Nos'] = reqNos.join(', ');
            }

            return row;
        });

        const ws = XLSX.utils.json_to_sheet(exportData);

        // Auto column widths for readability
        const headers = Object.keys(exportData[0] || {});
        const widths = headers.map((h) => Math.max(h.length, 12));
        exportData.forEach((r) => {
            headers.forEach((h, idx) => {
                const val = (r as any)[h];
                const len = (val ?? '').toString().length;
                widths[idx] = Math.min(60, Math.max(widths[idx], len));
            });
        });
        (ws as any)['!cols'] = widths.map((wch) => ({ wch }));

        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'Export');
        XLSX.writeFile(wb, `${fileName}.xlsx`);
    };

    const exportFinishCoaModalToExcel = useCallback(
        (filteredData: any[]) => {
            if (!filteredData || filteredData.length === 0) return;

            const dateStr = new Date().toISOString().slice(0, 10);
            const yearLabel = selectedFilterYear ?? 'All';
            const sectionLabel = finishCoaModalSection ?? 'all';
            const viewLabel = finishCoaViewMode ?? 'batch';
            const baseName = `Finish_COA_${finishCoaModalType}_${sectionLabel}_${viewLabel}_${yearLabel}_${dateStr}`;

            const wb = XLSX.utils.book_new();

            if (finishCoaViewMode === 'table') {
                const rows = filteredData.map((item: any, idx: number) => ({
                    'SR No.': idx + 1,
                    'Batch No': item.batchNumber || '',
                    'MFC': item.mfc || item.mfcNo || '',
                    'AR Number': item.arNumber || '',
                    [finishCoaModalType === 'matched' ? 'Product Code' : 'Item Code']: item.productCode || item.itemCode || '',
                    [finishCoaModalType === 'matched' ? 'Product Name' : 'Item Name']: item.productName || item.itemName || '',
                    ...(finishCoaModalType === 'matched'
                        ? { 'Test Date': item.testDate || '', Status: item.status || '', Manufacturer: item.manufacturer || '' }
                        : { 'MFG Date': item.mfgDate || '', 'Expiry Date': item.expiryDate || '' }),
                }));
                const ws = XLSX.utils.json_to_sheet(rows);
                XLSX.utils.book_append_sheet(wb, ws, 'Finish COA');
            } else if (finishCoaViewMode === 'material') {
                const grouped = new Map<string, any[]>();
                filteredData.forEach((item: any) => {
                    const key = (item.productCode || item.itemCode || 'N/A').toString();
                    if (!grouped.has(key)) grouped.set(key, []);
                    grouped.get(key)!.push(item);
                });

                const summaryRows = Array.from(grouped.entries()).map(([materialCode, items], idx) => ({
                    'SR No.': idx + 1,
                    [finishCoaModalType === 'matched' ? 'Product Code' : 'Item Code']: materialCode,
                    [finishCoaModalType === 'matched' ? 'Product Name' : 'Item Name']:
                        items?.[0]?.productName || items?.[0]?.itemName || '',
                    'Unique AR': new Set((items || []).map((i: any) => i.arNumber).filter(Boolean)).size,
                    Records: (items || []).length,
                }));
                const wsSummary = XLSX.utils.json_to_sheet(summaryRows);
                XLSX.utils.book_append_sheet(wb, wsSummary, 'Materials Summary');

                const detailRows = filteredData.map((item: any, idx: number) => ({
                    'SR No.': idx + 1,
                    [finishCoaModalType === 'matched' ? 'Product Code' : 'Item Code']: item.productCode || item.itemCode || '',
                    [finishCoaModalType === 'matched' ? 'Product Name' : 'Item Name']: item.productName || item.itemName || '',
                    'Batch No': item.batchNumber || '',
                    'MFC': item.mfc || item.mfcNo || '',
                    'AR Number': item.arNumber || '',
                    ...(finishCoaModalType === 'matched'
                        ? { 'Test Date': item.testDate || '', Status: item.status || '', Manufacturer: item.manufacturer || '' }
                        : { 'MFG Date': item.mfgDate || '', 'Expiry Date': item.expiryDate || '' }),
                }));
                const wsDetails = XLSX.utils.json_to_sheet(detailRows);
                XLSX.utils.book_append_sheet(wb, wsDetails, 'Material Details');
            } else {
                // batch/details mode
                const rows = filteredData.map((item: any) => {
                    const id = String(
                        item._finishCoaRowId ??
                            `${(item.batchNumber || '').toString().trim().toUpperCase()}_${item.itemCode}_${item.mfgDate}`
                    );
                    const coaLineItems = Array.isArray(item.coaLineItems) ? item.coaLineItems : [];
                    const arCount = typeof item.arCount === 'number' ? item.arCount : coaLineItems.length;
                    return {
                        id,
                        batchNo: item.batchNumber || '',
                        mfcNo: item.mfcNo || item.mfc || 'N/A',
                        productName: item.productName || item.itemName || 'N/A',
                        arCount,
                        batchSize: item.batchSize != null && item.batchSize !== '' ? String(item.batchSize) : 'N/A',
                        mfgDate: item.mfgDate || 'N/A',
                        expiryDate: item.expiryDate || 'N/A',
                        coaLineItems,
                    };
                });

                const sortedRows = [...rows].sort((a, b) => {
                    const col = finishCoaSortColumn;
                    let valA: any = (a as any)[col];
                    let valB: any = (b as any)[col];
                    if (col === 'arCount') {
                        valA = Number(a.arCount) || 0;
                        valB = Number(b.arCount) || 0;
                    }
                    if (typeof valA === 'string' && typeof valB === 'string') {
                        return finishCoaSortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
                    }
                    return finishCoaSortDirection === 'asc' ? valA - valB : valB - valA;
                });

                const batchSheetRows = sortedRows.map((r, idx) => ({
                    'SR No.': idx + 1,
                    'Batch No': r.batchNo,
                    'MFC No': r.mfcNo,
                    'Product Name': r.productName,
                    'AR Count': r.arCount,
                    'Batch Size': r.batchSize,
                    'MFG Date': r.mfgDate,
                    Expiry: r.expiryDate,
                }));
                const wsBatch = XLSX.utils.json_to_sheet(batchSheetRows);
                XLSX.utils.book_append_sheet(wb, wsBatch, 'Batch Summary');

                if (finishCoaModalType === 'matched') {
                    const lineRows: any[] = [];
                    sortedRows.forEach((r, batchIdx) => {
                        (r.coaLineItems || []).forEach((line: any, lineIdx: number) => {
                            lineRows.push({
                                'Batch SR': batchIdx + 1,
                                'Line SR': lineIdx + 1,
                                'Batch No': r.batchNo,
                                'MFC No': r.mfcNo,
                                'Batch Size': r.batchSize,
                                'MFG Date': r.mfgDate,
                                Expiry: r.expiryDate,
                                'AR Number': line.arNumber || '',
                                'Product Code': line.productCode || '',
                                'Product Name': line.productName || '',
                                'Test Date': line.testDate || '',
                                Status: line.status || '',
                                Manufacturer: line.manufacturer || '',
                            });
                        });
                    });
                    const wsLines = XLSX.utils.json_to_sheet(lineRows);
                    XLSX.utils.book_append_sheet(wb, wsLines, 'COA Line Items');
                }
            }

            XLSX.writeFile(wb, `${baseName}.xlsx`);
        },
        [
            finishCoaModalSection,
            finishCoaModalType,
            finishCoaSortColumn,
            finishCoaSortDirection,
            finishCoaViewMode,
            selectedFilterYear,
        ]
    );

    const exportRmCoaToExcelEnsureAr = useCallback(
        (data: any[], fileName: string) => {
            if (!data || data.length === 0) return;

            const deriveAr = (row: any): string => {
                const direct =
                    (row?.arNo ?? row?.arNumber ?? row?.arToken ?? row?.ar)?.toString().trim();
                if (direct) return direct;

                const fromBreakdown = Array.isArray(row?.arTokenBreakdown)
                    ? Array.from(
                          new Set(
                              row.arTokenBreakdown
                                  .map((x: any) => (x?.arToken ?? '').toString().trim())
                                  .filter(Boolean)
                          )
                      )
                    : [];
                if (fromBreakdown.length > 0) return fromBreakdown.join(', ');

                const fromItems = Array.isArray(row?.items)
                    ? Array.from(
                          new Set(
                              row.items.flatMap((it: any) => splitArNumbers(it?.arNo)).filter(Boolean)
                          )
                      )
                    : [];
                if (fromItems.length > 0) return fromItems.join(', ');

                return '';
            };

            const withAr = (data as any[])
                .map((r) => {
                    const ar = deriveAr(r);
                    return {
                        ...r,
                        // Prefer `arNo` because RM COA tables/search use `arNo`
                        arNo: (r?.arNo || ar) ?? '',
                        arNumber: (r?.arNumber || ar) ?? '',
                    };
                })
                .filter((r) => {
                    const ar = (r?.arNo ?? r?.arNumber ?? '').toString().trim();
                    return Boolean(ar);
                });

            handleExportToExcel(withAr, fileName);
        },
        [handleExportToExcel]
    );
    // Build map: batchNumber → manufacturing year (from allBatches raw data)
    const batchYearMap = useMemo(() => {
        const map = new Map<string, string>();
        (allBatches as any[]).forEach(b => {
            if (b.batchNumber) {
                const parts = (b.mfgDate || '').split('-');
                if (parts.length === 3) {
                    const y = parseInt(parts[2], 10);
                    if (!isNaN(y)) map.set(b.batchNumber, (y < 50 ? 2000 + y : 1900 + y).toString());
                }
            }
        });
        return map;
    }, [allBatches]);

    // Available years derived from manufacturing dates of all batches
    const availableYears = useMemo(() => {
        const years = new Set<string>();
        batchYearMap.forEach(yr => years.add(yr));
        return Array.from(years).sort((a, b) => Number(b) - Number(a));
    }, [batchYearMap]);

    // Filter formulas
    const filteredFormulas = useMemo(() => {
        let result = formulas;

        if (selectedFilterYear) {
            result = result.filter(f => {
                const batchNos: string[] = (f as any).uniqueBatchNumbers || [];
                return batchNos.some((bn: string) => batchYearMap.get(bn) === selectedFilterYear);
            });
        }

        if (selectedManufacturer) {
            result = result.filter(f =>
                (f.masterFormulaDetails?.manufacturer || 'Other') === selectedManufacturer
            );
        }

        if (searchTerm) {
            const term = searchTerm.toLowerCase().trim();

            // Allow searching by batch number and batch/item name using allBatches.
            const matchedItemCodesFromBatches = new Set<string>();
            if (term) {
                (allBatches as BatchItem[]).forEach((b) => {
                    const bn = (b.batchNumber || '').toLowerCase();
                    const itemName = (b.itemName || '').toLowerCase(); // "batch name" in UI
                    if (bn.includes(term) || itemName.includes(term)) {
                        const code = (b.itemCode || '').toString().trim();
                        if (code) matchedItemCodesFromBatches.add(code);
                    }
                });
            }

            result = result.filter((f) => {
                const master = f.masterFormulaDetails;
                const productCode = master.productCode || '';
                const uniqueBatchNos: string[] = (f as any).uniqueBatchNumbers || [];
                const hasBatchNoMatch = uniqueBatchNos.some((bn: string) => (bn || '').toLowerCase().includes(term));

                return (
                    master.masterCardNo?.toLowerCase().includes(term) ||
                    productCode.toLowerCase().includes(term) ||
                    master.productName?.toLowerCase().includes(term) ||
                    master.genericName?.toLowerCase().includes(term) ||
                    hasBatchNoMatch ||
                    matchedItemCodesFromBatches.has(productCode)
                );
            });
        }

        // Sort by MFC Number if enabled
        if (mfcSortOrder !== 'none') {
            result = [...result].sort((a, b) => {
                const mfcA = a.masterFormulaDetails?.masterCardNo || '';
                const mfcB = b.masterFormulaDetails?.masterCardNo || '';
                const comparison = mfcA.localeCompare(mfcB, undefined, { numeric: true, sensitivity: 'base' });
                return mfcSortOrder === 'asc' ? comparison : -comparison;
            });
        }

        return result;
    }, [formulas, selectedFilterYear, selectedManufacturer, searchTerm, mfcSortOrder, astRstData, batchYearMap, allBatches]);

    // Separate formulas into categories with DEDUPLICATION by product code
    const { mainFormulas, lowBatchFormulas, noBatchFormulas, placeboFormulas, sectionBatchTotals } = useMemo(() => {
        const placebo: FormulaRecord[] = [];
        const lowBatch: FormulaRecord[] = [];
        const noBatch: FormulaRecord[] = [];
        const main: FormulaRecord[] = [];

        filteredFormulas.forEach(f => {
            const productName = f.masterFormulaDetails.productName?.toLowerCase() || '';
            // Include both 'placebo' and 'mediafill' in placebo section
            const isPlaceboOrMediafill = productName.includes('placebo') || productName.includes('mediafill') || productName.includes('media fill');
            const batchCount = f.totalBatchCount || 0;

            if (isPlaceboOrMediafill) {
                placebo.push(f);
            } else if (batchCount === 0) {
                // New category: MFCs with NO batches at all
                noBatch.push(f);
            } else if (batchCount < 3) {
                // Low batch: 1-2 batches
                lowBatch.push(f);
            } else {
                main.push(f);
            }
        });

        // Calculate total batches for each section - DEDUPLICATED by PRODUCT CODE
        // The key insight: batches are matched by product code (itemCode)
        // If the same product code appears in multiple formulas, we only count it ONCE

        // Track which product codes we've already counted (globally across all sections)
        const countedProductCodes = new Set<string>();

        // Helper function to get all product codes from a formula
        const getFormulaProductCodes = (f: FormulaRecord): string[] => {
            const codes: string[] = [];

            // Main product code
            const mainCode = f.masterFormulaDetails?.productCode;
            if (mainCode && mainCode !== 'N/A') codes.push(mainCode);

            // Filling details product codes
            if (f.fillingDetails && Array.isArray(f.fillingDetails)) {
                f.fillingDetails.forEach((fd: FillingDetail) => {
                    if (fd.productCode && fd.productCode !== 'N/A' && !codes.includes(fd.productCode)) {
                        codes.push(fd.productCode);
                    }
                });
            }

            // Process filling products
            if (f.processes && Array.isArray(f.processes)) {
                f.processes.forEach((p: ProcessData) => {
                    if (p.fillingProducts && Array.isArray(p.fillingProducts)) {
                        p.fillingProducts.forEach((fp: AsepticFillingProduct) => {
                            if (fp.productCode && !codes.includes(fp.productCode)) {
                                codes.push(fp.productCode);
                            }
                        });
                    }
                });
            }

            return codes;
        };

        let mainBatchTotal = 0;
        let lowBatchTotal = 0;
        let noBatchTotal = 0;
        let placeboBatchTotal = 0;

        // Calculate for main formulas (3+ batches)
        main.forEach(f => {
            const productCodes = getFormulaProductCodes(f);
            productCodes.forEach(code => {
                if (!countedProductCodes.has(code)) {
                    countedProductCodes.add(code);
                    mainBatchTotal += batchCounts[code] || 0;
                }
            });
        });

        // Calculate for low batch formulas (1-2 batches)
        lowBatch.forEach(f => {
            const productCodes = getFormulaProductCodes(f);
            productCodes.forEach(code => {
                if (!countedProductCodes.has(code)) {
                    countedProductCodes.add(code);
                    lowBatchTotal += batchCounts[code] || 0;
                }
            });
        });

        // No batch formulas always have 0
        noBatch.forEach(f => {
            const productCodes = getFormulaProductCodes(f);
            productCodes.forEach(code => {
                if (!countedProductCodes.has(code)) {
                    countedProductCodes.add(code);
                    noBatchTotal += batchCounts[code] || 0; // Should be 0
                }
            });
        });

        // Calculate for placebo formulas
        placebo.forEach(f => {
            const productCodes = getFormulaProductCodes(f);
            productCodes.forEach(code => {
                if (!countedProductCodes.has(code)) {
                    countedProductCodes.add(code);
                    placeboBatchTotal += batchCounts[code] || 0;
                }
            });
        });

        return {
            mainFormulas: main,
            lowBatchFormulas: lowBatch,
            noBatchFormulas: noBatch,
            placeboFormulas: placebo,
            sectionBatchTotals: {
                main: mainBatchTotal,
                lowBatch: lowBatchTotal,
                noBatch: noBatchTotal,
                placebo: placeboBatchTotal,
                // Total should now match actual batch count
                totalCounted: mainBatchTotal + lowBatchTotal + noBatchTotal + placeboBatchTotal
            }
        };
    }, [filteredFormulas, batchCounts]);


    const fetchFormulas = useCallback(async () => {
        setIsLoading(true);
        try {
            const response = await fetch('/api/formula?page=1&limit=1000');
            const data: FormulaListResponse = await response.json();
            if (data.success) {
                const normBatch = (b: string | null | undefined) => (b || '').trim().toUpperCase();
                setFormulas(data.data);
                if (data.batchCounts) setBatchCounts(data.batchCounts);
                if (data.unmatchedBatches) setUnmatchedBatches(data.unmatchedBatches);
                // Set global RM matching data for capsule indicator
                if (data.globalRmDataMatched !== undefined) setGlobalRmDataMatched(data.globalRmDataMatched);
                if (data.globalRmDataUnmatched !== undefined) setGlobalRmDataUnmatched(data.globalRmDataUnmatched);
                // Set global PPM and PM matching data
                if (data.globalPpmDataMatched !== undefined) setGlobalPpmDataMatched(data.globalPpmDataMatched);
                if (data.globalPpmDataUnmatched !== undefined) setGlobalPpmDataUnmatched(data.globalPpmDataUnmatched);
                if (data.globalPmDataMatched !== undefined) setGlobalPmDataMatched(data.globalPmDataMatched);
                if (data.globalPmDataUnmatched !== undefined) setGlobalPmDataUnmatched(data.globalPmDataUnmatched);
                // Store batch numbers with RM data for per-section RM calculation
                if (data.rmBatchNumbersList) setRmBatchNumbers(new Set(data.rmBatchNumbersList.map(normBatch).filter(Boolean)));
                // Store batch numbers with PPM and PM data for per-section capsule calculation
                if (data.ppmBatchNumbersList) setPpmBatchNumbers(new Set(data.ppmBatchNumbersList.map(normBatch).filter(Boolean)));
                if (data.pmBatchNumbersList) setPmBatchNumbers(new Set(data.pmBatchNumbersList.map(normBatch).filter(Boolean)));
                // Store batch numbers that are material-qualified for per-section MAT calculation
                if (data.materialQualifiedBatchNumbersList) setMaterialQualifiedBatchNumbers(new Set(data.materialQualifiedBatchNumbersList.map(normBatch).filter(Boolean)));
                // Set global Material Qualification data for capsule indicator
                if (data.globalMaterialQualified !== undefined) setGlobalMaterialQualified(data.globalMaterialQualified);
                if (data.globalMaterialUnqualified !== undefined) setGlobalMaterialUnqualified(data.globalMaterialUnqualified);
                // Set global PM COA data for capsule indicator
                if (data.globalPmCoaQualified !== undefined) setGlobalPmCoaQualified(data.globalPmCoaQualified);
                if (data.globalPmCoaUnqualified !== undefined) setGlobalPmCoaUnqualified(data.globalPmCoaUnqualified);
                // Set global PPM COA data for capsule indicator
                if (data.globalPpmCoaQualified !== undefined) setGlobalPpmCoaQualified(data.globalPpmCoaQualified);
                if (data.globalPpmCoaUnqualified !== undefined) setGlobalPpmCoaUnqualified(data.globalPpmCoaUnqualified);
                // Set PM COA inward qualified batch numbers list
                if (data.pmCoaInwardQualifiedBatchNumbersList) setPmCoaInwardQualifiedBatchNumbers(new Set(data.pmCoaInwardQualifiedBatchNumbersList));
                if (data.ppmCoaInwardQualifiedBatchNumbersList) setPpmCoaInwardQualifiedBatchNumbers(new Set(data.ppmCoaInwardQualifiedBatchNumbersList));
                // Set global Bulk COA data for capsule indicator
                if (data.globalBulkCoaQualified !== undefined) setGlobalBulkCoaQualified(data.globalBulkCoaQualified);
                if (data.globalBulkCoaUnqualified !== undefined) setGlobalBulkCoaUnqualified(data.globalBulkCoaUnqualified);
                // Store batch numbers that have Bulk COA data for per-section calculation
                if (data.bulkCoaQualifiedBatchNumbersList) setBulkCoaQualifiedBatchNumbers(new Set(data.bulkCoaQualifiedBatchNumbersList.map(normBatch).filter(Boolean)));
                // Set global Finish COA data for capsule indicator
                if (data.globalFinishCoaQualified !== undefined) setGlobalFinishCoaQualified(data.globalFinishCoaQualified);
                if (data.globalFinishCoaUnqualified !== undefined) setGlobalFinishCoaUnqualified(data.globalFinishCoaUnqualified);
                // Store batch numbers that have Finish COA data for per-section calculation
                if (data.finishCoaQualifiedBatchNumbersList) setFinishCoaQualifiedBatchNumbers(new Set(data.finishCoaQualifiedBatchNumbersList.map(normBatch).filter(Boolean)));
                // Set global RM COA unique AR numbers count for footer display
                if (data.globalRmCoaUniqueArNumbersFound !== undefined) setGlobalRmCoaUniqueArNumbersFound(data.globalRmCoaUniqueArNumbersFound);
                if (data.globalRmCoaUniqueArNumbersMissing !== undefined) setGlobalRmCoaUniqueArNumbersMissing(data.globalRmCoaUniqueArNumbersMissing);
            }
        } catch (error) {
            console.error('Error fetching formulas:', error);
        } finally {
            setIsLoading(false);
        }
    }, []);

    // Fetch batch reconciliation summary
    // Fetch all batches for batch section
    const fetchAllBatches = useCallback(async () => {
        setIsBatchesLoading(true);
        try {
            const response = await fetch('/api/batch?page=1&limit=10000');
            const data = await response.json();
            if (data.success && data.data) {
                const items: any[] = [];
                data.data.forEach((record: any) => {
                    record.batches.forEach((batch: any) => {
                        items.push({
                            ...batch,
                            sourceFileName: record.fileName,
                            sourceCompanyName: record.companyName,
                            uploadedAt: record.uploadedAt,
                        });
                    });
                });
                setAllBatches(items);
            }
        } catch (error) {
            console.error('Error fetching batches:', error);
        } finally {
            setIsBatchesLoading(false);
        }
    }, []);

    const fetchTrialBatches = useCallback(async () => {
        try {
            const res = await fetch('/api/trial-batch');
            const json = await res.json();
            if (json.success) {
                setTrialBatchNumbers(new Set((json.data as { batchNumber: string }[]).map(d => d.batchNumber)));
            }
        } catch { /* ignore */ }
    }, []);

    const toggleTrialBatch = async (batchNumber: string, itemCode: string) => {
        const isTrial = trialBatchNumbers.has(batchNumber);
        try {
            if (isTrial) {
                await fetch('/api/trial-batch', {
                    method: 'DELETE',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ batchNumber, itemCode: itemCode || '' }),
                });
                setTrialBatchNumbers(prev => { const next = new Set(prev); next.delete(batchNumber); return next; });
            } else {
                await fetch('/api/trial-batch', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ batchNumber, itemCode: itemCode || '' }),
                });
                setTrialBatchNumbers(prev => new Set([...prev, batchNumber]));
            }
        } catch { /* ignore */ }
    };

    const fetchBatchReconciliation = useCallback(async () => {
        try {
            const response = await fetch('/api/reconciliation');
            const data = await response.json();
            if (data.success && data.data?.batchReconciliation) {
                setBatchReconciliation(data.data.batchReconciliation);
            }
        } catch (error) {
            console.error('Error fetching batch reconciliation:', error);
        }
    }, []);

    // Fetch RM COA batch-wise data for selected year (for header capsules + per-section calculation)
    useEffect(() => {
        let cancelled = false;
        (async () => {
            try {
                const normBatch = (b: string | null | undefined) => (b || '').trim().toUpperCase();
                const qs = selectedFilterYear
                    ? new URLSearchParams({ year: selectedFilterYear })
                    : new URLSearchParams({ scope: 'all' });
                // Drill `requisition_found` returns requisition-found batches with COA status per batch (batch-wise).
                const drillQs = new URLSearchParams(qs);
                drillQs.set('drill', 'requisition_found');
                const res = await fetch(`/api/requisition/rm-coa-verification?${drillQs.toString()}`);
                const data = await res.json();
                if (cancelled) return;
                if (data?.success && Array.isArray(data?.rows)) {
                    const reqFound = new Set<string>();
                    const coaFound = new Set<string>();
                    const arFound = new Set<string>();
                    const arMissing = new Set<string>();
                    setRmCoaVerificationRows(data.rows);
                    // Rows can be line-level; we convert to batch-wise sets.
                    data.rows.forEach((r: any) => {
                        const bn = normBatch(r?.batchNumber);
                        if (!bn) return;
                        reqFound.add(bn);
                        // If any row says found, keep found (defensive).
                        const status = (r?.coaStatus || '').toString();
                        if (status === 'COA Found') coaFound.add(bn);
                        splitArNumbers(r?.arNo).forEach(ar => {
                            if (status === 'COA Found') arFound.add(ar);
                            else arMissing.add(ar);
                        });
                    });
                    arFound.forEach(ar => arMissing.delete(ar));
                    const missingCount = Math.max(0, reqFound.size - coaFound.size);
                    setRmCoaReqFoundBatchNumbers(reqFound);
                    setRmCoaFoundBatchNumbers(coaFound);
                    setGlobalRmCoaBatchesFound(coaFound.size);
                    setGlobalRmCoaBatchesMissing(missingCount);
                    setGlobalRmCoaUniqueArNumbersFound(arFound.size);
                    setGlobalRmCoaUniqueArNumbersMissing(arMissing.size);
                } else {
                    setRmCoaVerificationRows([]);
                    setRmCoaReqFoundBatchNumbers(new Set());
                    setRmCoaFoundBatchNumbers(new Set());
                    setGlobalRmCoaBatchesFound(0);
                    setGlobalRmCoaBatchesMissing(0);
                    setGlobalRmCoaUniqueArNumbersFound(0);
                    setGlobalRmCoaUniqueArNumbersMissing(0);
                }
            } catch {
                if (cancelled) return;
                setRmCoaVerificationRows([]);
                setRmCoaReqFoundBatchNumbers(new Set());
                setRmCoaFoundBatchNumbers(new Set());
                setGlobalRmCoaBatchesFound(0);
                setGlobalRmCoaBatchesMissing(0);
                setGlobalRmCoaUniqueArNumbersFound(0);
                setGlobalRmCoaUniqueArNumbersMissing(0);
            }
        })();
        return () => { cancelled = true; };
    }, [selectedFilterYear]);

