    const closePmDataModal = useCallback(() => {
        setShowPmDataModal(false);
        setPmModalData([]);
        setPmModalError(null);
        setPmSearchQuery('');
        setPmSearchField('all');
        setPmModalScopeLabel('');
    }, []);

    // Open Material Qualification Modal - show materials with/without RM COA data
    const openMatDataModal = useCallback(async (
        type: 'qualified' | 'unqualified',
        section: 'main' | 'lowBatch' | 'noBatch' | 'placebo' | 'all' = 'all',
        explicitFormulas: any[] = [],
        defaultViewMode: 'file' | 'table' | 'batch' | 'material' = 'batch'
    ) => {
        setShowMatDataModal(true);
        setMatModalType(type);
        setMatModalSection(section);
        setIsMatModalLoading(true);
        setRmCoaCapsuleBatchCount(0); // Will fall back to recomputed count
        setMatModalError(null);
        setMatModalData([]);
        setExpandedMatArNumbers(new Set());
        setExpandedMatBatchNumbers(new Set());
        setExpandedMatMaterialCodes(new Set());
        setMatViewMode(defaultViewMode);
        setMatSearchQuery('');

        // Set subtitle based on context
        const yearSuffix = selectedFilterYear ? ` • Year: ${selectedFilterYear}` : '';
        if (explicitFormulas && explicitFormulas.length === 1) {
            const mfc = explicitFormulas[0].masterFormulaDetails?.masterCardNo || 'Unknown MFC';
            const product = explicitFormulas[0].masterFormulaDetails?.productName || '';
            setMatModalSubtitle(`Filtered by MFC: ${mfc} - ${product}${yearSuffix}`);
        } else if (section !== 'all') {
            setMatModalSubtitle(`Filtered by ${section === 'main' ? 'MFCs with 3+ batches' : section === 'lowBatch' ? 'Low Batch MFCs' : section === 'noBatch' ? 'No Batch MFCs' : 'Placebo & Media Fill'}${yearSuffix}`);
        } else {
            setMatModalSubtitle(selectedFilterYear ? `Year: ${selectedFilterYear}` : '');
        }

        // Get MFC numbers for the selected section
        const getSectionMfcNumbers = (): Set<string> => {
            const mfcNumbers = new Set<string>();

            // If explicit formulas provided (preferred), use them
            if (explicitFormulas && explicitFormulas.length > 0) {
                explicitFormulas.forEach((f: any) => {
                    const masterCardNo = (f.masterFormulaDetails?.masterCardNo || '').trim().toUpperCase();
                    if (masterCardNo) {
                        mfcNumbers.add(masterCardNo);
                    }
                });
                return mfcNumbers;
            }

            // Fallback: Get the relevant formulas based on section (using internal state)
            let sectionFormulas: any[] = [];
            if (section === 'main') {
                sectionFormulas = formulas.filter((f: any) => {
                    const totalBatchCount = f.totalBatchCount || 0;
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    const isPlacebo = productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                    return totalBatchCount >= 3 && !isPlacebo;
                });
            } else if (section === 'lowBatch') {
                sectionFormulas = formulas.filter((f: any) => {
                    const totalBatchCount = f.totalBatchCount || 0;
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    const isPlacebo = productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                    return totalBatchCount >= 1 && totalBatchCount <= 2 && !isPlacebo;
                });
            } else if (section === 'noBatch') {
                sectionFormulas = formulas.filter((f: any) => {
                    const totalBatchCount = f.totalBatchCount || 0;
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    const isPlacebo = productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                    return totalBatchCount === 0 && !isPlacebo;
                });
            } else if (section === 'placebo') {
                sectionFormulas = formulas.filter((f: any) => {
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    return productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                });
            } else {
                // 'all' - use all formulas
                sectionFormulas = formulas;
            }

            sectionFormulas.forEach((f: any) => {
                const masterCardNo = (f.masterFormulaDetails?.masterCardNo || '').trim().toUpperCase();
                if (masterCardNo) {
                    mfcNumbers.add(masterCardNo);
                }
            });

            return mfcNumbers;
        };

        const sectionMfcNumbers = getSectionMfcNumbers();

        // ENHANCEMENT: Build a list of valid product codes for MFC-specific filtering
        // When a single formula is selected, we want to only show data for batches belonging to that MFC
        const validProductCodes = new Set<string>();
        if (explicitFormulas && explicitFormulas.length > 0) {
            explicitFormulas.forEach((formula: any) => {
                const mainCode = formula.masterFormulaDetails?.productCode;
                if (mainCode && mainCode !== 'N/A') validProductCodes.add(mainCode);
                if (formula.fillingDetails && Array.isArray(formula.fillingDetails)) {
                    formula.fillingDetails.forEach((fd: any) => {
                        if (fd.productCode && fd.productCode !== 'N/A') validProductCodes.add(fd.productCode);
                    });
                }
                if (formula.processes && Array.isArray(formula.processes)) {
                    formula.processes.forEach((p: any) => {
                        if (p.fillingProducts && Array.isArray(p.fillingProducts)) {
                            p.fillingProducts.forEach((fp: any) => {
                                if (fp.productCode) validProductCodes.add(fp.productCode);
                            });
                        }
                    });
                }
            });
        }

        try {
            if (type === 'qualified') {
                // Qualified: Show UNIQUE BATCHES that have NO missing RM COA ARs
                // This matches the capsule logic: found = total MFC batches - batches with missing ARs
                const rmCoaResponse = await fetch('/api/rmcoa');
                const rmCoaData = await rmCoaResponse.json();

                if (rmCoaData.success) {
                    // If filtering by specific MFC, we need to fetch requisition data to get batch context
                    if (validProductCodes.size > 0) {
                        // Fetch requisition data to map AR numbers to batches and MFCs
                        const requisitionResponse = await fetch('/api/requisition/materials?type=RM&pageSize=100000');
                        const requisitionData = await requisitionResponse.json();

                        // Fetch Inward Data for validation (same as missing logic)
                        const inwardArResponse = await fetch('/api/inward/ar-numbers');
                        const inwardArData = await inwardArResponse.json();
                        const inwardNumbersResponse = await fetch('/api/inward/inward-numbers');
                        const inwardNumbersData = await inwardNumbersResponse.json();

                        // Build case-insensitive set of all AR numbers in Inward Register
                        const inwardArNumbersSet = new Set<string>();
                        if (inwardArData.success && inwardArData.arNumbers) {
                            inwardArData.arNumbers.forEach((arNumber: string) => {
                                if (arNumber && arNumber.trim() !== '') {
                                    const trimmedAr = arNumber.trim().toUpperCase();
                                    inwardArNumbersSet.add(trimmedAr);
                                    const baseAr = trimmedAr.split('.')[0];
                                    if (baseAr && baseAr !== trimmedAr) inwardArNumbersSet.add(baseAr);
                                }
                            });
                        }
                        if (inwardNumbersData.success && inwardNumbersData.inwardNumbers) {
                            inwardNumbersData.inwardNumbers.forEach((inwardNo: string) => {
                                if (inwardNo && inwardNo.trim() !== '') {
                                    const trimmedInward = inwardNo.trim().toUpperCase();
                                    inwardArNumbersSet.add(trimmedInward);
                                    const baseInward = trimmedInward.split('.')[0];
                                    if (baseInward && baseInward !== trimmedInward) inwardArNumbersSet.add(baseInward);
                                }
                            });
                        }

                        // Build batch to product code mapping (year-filtered)
                        const batchToProductCode = new Map<string, string>();
                        if (yearFilteredBatches && yearFilteredBatches.length > 0) {
                            yearFilteredBatches.forEach((batch: any) => {
                                if (batch.batchNumber && batch.itemCode) {
                                    batchToProductCode.set(batch.batchNumber.trim().toUpperCase(), batch.itemCode);
                                }
                            });
                        }

                        // Build a set of AR numbers that exist in RM COA
                        const rmCoaArNumbers = new Set<string>();
                        rmCoaData.data.forEach((c: any) => {
                            if (c.arNo && c.arNo.trim() !== '') {
                                rmCoaArNumbers.add(c.arNo.trim());
                            }
                        });

                        // Helper function to check if an AR number is an RM-type AR number
                        const isRmArNumber = (arNo: string): boolean => {
                            const upper = arNo.toUpperCase();
                            if (upper.includes('PRM')) return false;
                            if (upper.includes('ORM') || upper.includes('ARM')) return true;
                            return true;
                        };

                        const normalizeBatchRm = (b: string | null | undefined) => (b || '').trim().toUpperCase();

                        // Step 1: Batches for this MFC in the selected year — normalize keys so requisition rows match system batches
                        const mfcBatchesNorm = new Set<string>();
                        const rmBatchNormToDisplay = new Map<string, string>();
                        yearFilteredBatches.forEach((batch: any) => {
                            if (batch.batchNumber && batch.itemCode && validProductCodes.has(batch.itemCode)) {
                                const bn = normalizeBatchRm(batch.batchNumber);
                                if (bn) {
                                    mfcBatchesNorm.add(bn);
                                    if (!rmBatchNormToDisplay.has(bn)) {
                                        rmBatchNormToDisplay.set(bn, batch.batchNumber);
                                    }
                                }
                            }
                        });

                        // Step 2: Find batches that have ANY missing RM COA ARs (same logic as capsule)
                        const batchesWithMissingArsNorm = new Set<string>();
                        if (requisitionData.success && requisitionData.materials) {
                            mfcBatchesNorm.forEach(batchNoNorm => {
                                let hasMissingAr = false;

                                requisitionData.materials.forEach((m: any) => {
                                    if (m.batchNumber && normalizeBatchRm(m.batchNumber) === batchNoNorm) {
                                        const arNo = (m.arNo || '').trim();
                                        // Skip dotted AR numbers
                                        if (arNo && isRmArNumber(arNo) && !/\.\d/.test(arNo)) {
                                            const arNoUpper = arNo.toUpperCase();
                                            const arNoBase = arNoUpper.split('.')[0];
                                            const isInCoa = rmCoaArNumbers.has(arNo);
                                            const isInInward = inwardArNumbersSet.has(arNoUpper) || inwardArNumbersSet.has(arNoBase);
                                            // Missing = Not in COA AND Present in Inward
                                            if (!isInCoa && isInInward) {
                                                hasMissingAr = true;
                                            }
                                        }
                                    }
                                });

                                if (hasMissingAr) {
                                    batchesWithMissingArsNorm.add(batchNoNorm);
                                }
                            });
                        }

                        // Step 3: Found batches = MFC batches that have NO missing ARs
                        const foundBatchesNorm = new Set<string>();
                        mfcBatchesNorm.forEach(batchNoNorm => {
                            if (!batchesWithMissingArsNorm.has(batchNoNorm)) {
                                foundBatchesNorm.add(batchNoNorm);
                            }
                        });

                        // Step 4: Build materials list for found batches with their AR details
                        const materials: any[] = [];

                        if (requisitionData.success && requisitionData.materials) {
                            const batchDataMap = new Map<string, any[]>();

                            requisitionData.materials.forEach((m: any) => {
                                const bn = m.batchNumber ? normalizeBatchRm(m.batchNumber) : '';
                                if (bn && foundBatchesNorm.has(bn)) {
                                    const arNo = (m.arNo || '').trim();
                                    if (arNo && isRmArNumber(arNo) && rmCoaArNumbers.has(arNo)) {
                                        if (!batchDataMap.has(bn)) {
                                            batchDataMap.set(bn, []);
                                        }
                                        batchDataMap.get(bn)!.push(m);
                                    }
                                }
                            });

                            // Create one record per batch with aggregated AR info
                            foundBatchesNorm.forEach(batchNoNorm => {
                                const batchMaterials = batchDataMap.get(batchNoNorm) || [];
                                const arNumbers = new Set<string>();
                                let materialCode = 'N/A';
                                let materialName = 'Unknown';
                                let formulaMfc = 'N/A';
                                let totalQty = 0;

                                batchMaterials.forEach((m: any) => {
                                    if (m.arNo) arNumbers.add(m.arNo.trim());
                                    if (m.materialCode && materialCode === 'N/A') materialCode = m.materialCode;
                                    if ((m.materialName || m.itemName) && materialName === 'Unknown') {
                                        materialName = m.materialName || m.itemName;
                                    }
                                    if (m.mfcNo && formulaMfc === 'N/A') formulaMfc = (m.mfcNo || '').trim().toUpperCase();
                                    totalQty += m.quantityToIssue || m.quantityRequired || 0;
                                });

                                materials.push({
                                    batchNumber: rmBatchNormToDisplay.get(batchNoNorm) || batchNoNorm,
                                    materialCode: materialCode,
                                    materialName: materialName,
                                    formulaMfc: formulaMfc,
                                    arNo: Array.from(arNumbers).join(', '),
                                    arCount: arNumbers.size,
                                    quantityToIssue: totalQty,
                                    status: 'All ARs Found in RM COA',
                                    sourceFile: 'RM COA',
                                });
                            });
                        }

                        setMatModalData(materials);
                    } else {
                        // No MFC filtering - show all RM COA data
                        const materials = rmCoaData.data.map((coa: any) => ({
                            arNo: coa.arNo,
                            materialCode: coa.materialCode,
                            materialName: coa.materialName,
                            testDate: coa.testDate || 'N/A',
                            status: coa.status || 'N/A',
                            sourceFile: coa.sourceFile,
                        }));
                        setMatModalData(materials);
                    }
                } else {
                    setMatModalError(rmCoaData.message || 'Failed to fetch RM COA data');
                }
            } else {
                // Unqualified: Show RM AR numbers that exist in Requisition but NOT in COA
                // First get all AR numbers from RM COA
                const rmCoaResponse = await fetch('/api/rmcoa');
                const rmCoaData = await rmCoaResponse.json();

                // Fetch Inward Data for validation
                const inwardArResponse = await fetch('/api/inward/ar-numbers');
                const inwardArData = await inwardArResponse.json();
                const inwardNumbersResponse = await fetch('/api/inward/inward-numbers');
                const inwardNumbersData = await inwardNumbersResponse.json();

                // Build case-insensitive set of all AR numbers/Inward numbers in Inward Register
                const inwardArNumbersSet = new Set<string>();
                if (inwardArData.success && inwardArData.arNumbers) {
                    inwardArData.arNumbers.forEach((arNumber: string) => {
                        if (arNumber && arNumber.trim() !== '') {
                            const trimmedAr = arNumber.trim().toUpperCase();
                            inwardArNumbersSet.add(trimmedAr);
                            const baseAr = trimmedAr.split('.')[0];
                            if (baseAr && baseAr !== trimmedAr) inwardArNumbersSet.add(baseAr);
                        }
                    });
                }
                if (inwardNumbersData.success && inwardNumbersData.inwardNumbers) {
                    inwardNumbersData.inwardNumbers.forEach((inwardNo: string) => {
                        if (inwardNo && inwardNo.trim() !== '') {
                            const trimmedInward = inwardNo.trim().toUpperCase();
                            inwardArNumbersSet.add(trimmedInward);
                            const baseInward = trimmedInward.split('.')[0];
                            if (baseInward && baseInward !== trimmedInward) inwardArNumbersSet.add(baseInward);
                        }
                    });
                }

                // Build a set of AR numbers that exist in RM COA
                const rmCoaArNumbers = new Set<string>();
                if (rmCoaData.success && rmCoaData.data) {
                    rmCoaData.data.forEach((c: any) => {
                        if (c.arNo && c.arNo.trim() !== '') {
                            rmCoaArNumbers.add(c.arNo.trim());
                        }
                    });
                }

                // Fetch AR numbers from RM requisition data
                const requisitionResponse = await fetch('/api/requisition/materials?type=RM&pageSize=100000');
                const requisitionData = await requisitionResponse.json();

                // Helper function to check if an AR number is an RM-type AR number
                const isRmArNumber = (arNo: string): boolean => {
                    const upper = arNo.toUpperCase();
                    // Exclude AR numbers containing 'PRM' (PPM type)
                    if (upper.includes('PRM')) return false;
                    // Include AR numbers containing 'ORM' or 'ARM' (RM type)
                    if (upper.includes('ORM') || upper.includes('ARM')) return true;
                    return true;
                };

                // Build AR number-centric data structure
                // Show AR numbers from Requisition that are NOT in COA
                // Filter to only include entries for MFCs in the selected section
                const arNumberData: any[] = [];


                if (requisitionData.success && requisitionData.materials) {
                    // Fetch batch data to map batch numbers to product codes for accurate filtering (year-filtered)
                    const batchToProductCode = new Map<string, string>();
                    if (yearFilteredBatches && yearFilteredBatches.length > 0) {
                        yearFilteredBatches.forEach((batch: any) => {
                            if (batch.batchNumber && batch.itemCode) {
                                batchToProductCode.set(batch.batchNumber.trim().toUpperCase(), batch.itemCode);
                            }
                        });
                    }

                    requisitionData.materials.forEach((m: any) => {
                        if (m.arNo && m.arNo.trim() !== '') {
                            const arNo = m.arNo.trim();
                            // Skip dotted AR numbers (internal reference data)
                            if (/\.\d/.test(arNo)) return;

                            const mfcNo = (m.mfcNo || '').trim().toUpperCase();

                            // Also check with trimmed version
                            const isMfcInSection = section === 'all' || sectionMfcNumbers.has(mfcNo);

                            // ENHANCEMENT: Additional filtering for MFC-specific views
                            // If we have explicit formulas (single MFC view), also verify the batch belongs to this MFC's product codes
                            let batchBelongsToMfc = true;
                            if (validProductCodes.size > 0 && m.batchNumber) {
                                const batchProductCode = batchToProductCode.get(m.batchNumber.trim().toUpperCase());
                                if (batchProductCode) {
                                    batchBelongsToMfc = validProductCodes.has(batchProductCode);
                                } else {
                                    // STRICT: If batch not found in allBatches, skip it (don't include orphan batches)
                                    batchBelongsToMfc = false;
                                }
                            }

                            const arNoUpper = arNo.toUpperCase();
                            const arNoBase = arNoUpper.split('.')[0];
                            // Missing = Not in COA AND Present in Inward Register
                            const isInInward = inwardArNumbersSet.has(arNoUpper) || inwardArNumbersSet.has(arNoBase);

                            // Only include RM-type AR numbers that are NOT in COA, belong to section, match batch, AND match Inward Register
                            if (isRmArNumber(arNo) && !rmCoaArNumbers.has(arNo) && isMfcInSection && batchBelongsToMfc && isInInward) {
                                arNumberData.push({
                                    arNo: arNo,
                                    materialCode: m.materialCode || 'N/A',
                                    materialName: m.materialName || 'Unknown',
                                    formulaMfc: mfcNo || 'N/A',
                                    batchNumber: m.batchNumber || 'N/A',
                                    itemName: m.itemName || 'N/A',
                                    quantityRequired: m.quantityRequired || 0,
                                    quantityToIssue: m.quantityToIssue || 0,
                                    unit: m.unit || 'N/A',
                                    grNo: m.grNo || 'N/A',
                                    vendorCode: m.vendorCode || 'N/A',
                                    expiryDate: m.expiryDate || 'N/A',
                                    mfgDate: m.mfgDate || 'N/A',
                                    binCode: m.binCode || 'N/A',
                                    status: 'Missing in COA',
                                    hasArInRequisition: true,
                                });
                            }
                        }
                    });
                }

                setMatModalData(arNumberData);
            }
        } catch (error) {
            console.error('Error fetching material qualification data:', error);
            setMatModalError('Failed to fetch data');
        } finally {
            setIsMatModalLoading(false);
        }
    }, [formulas, batchCounts, yearFilteredBatches]);

    const closeMatDataModal = useCallback(() => {
        setShowMatDataModal(false);
        setMatModalData([]);
        setMatModalError(null);
        setExpandedMatArNumbers(new Set());
    }, []);

    // Open PM COA Modal - show PM materials with/without PM COA data (Inward Qualified)
    const openPmCoaModal = useCallback(async (
        type: 'qualified' | 'unqualified',
        section: 'main' | 'lowBatch' | 'noBatch' | 'placebo' | 'all' = 'all',
        explicitFormulas: any[] = [],
        defaultViewMode: 'ar' | 'table' | 'batch' = 'batch'
    ) => {
        setShowPmCoaModal(true);
        setPmCoaModalType(type);
        setPmCoaModalSection(section);
        setIsPmCoaModalLoading(true);
        setPmCoaCapsuleBatchCount(0); // Will fall back to recomputed count
        setPmCoaModalError(null);
        setPmCoaModalData([]);
        setExpandedPmCoaArNumbers(new Set());
        setExpandedPmCoaBatchNumbers(new Set());
        setPmCoaViewMode(defaultViewMode);
        setPmCoaModalPrimaryMetric(defaultViewMode === 'ar' ? 'ar' : 'batches');

        // Set subtitle based on context
        const pmYearSuffix = selectedFilterYear ? ` • Year: ${selectedFilterYear}` : '';
        if (explicitFormulas && explicitFormulas.length === 1) {
            const mfc = explicitFormulas[0].masterFormulaDetails?.masterCardNo || 'Unknown MFC';
            const product = explicitFormulas[0].masterFormulaDetails?.productName || '';
            setPmCoaModalSubtitle(`Filtered by MFC: ${mfc} - ${product}${pmYearSuffix}`);
        } else if (section !== 'all') {
            setPmCoaModalSubtitle(`Filtered by ${section === 'main' ? 'MFCs with 3+ Batches' : section === 'lowBatch' ? 'Low Batch MFCs' : section === 'noBatch' ? 'No Batch MFCs' : 'Placebo & Media Fill'}${pmYearSuffix}`);
        } else {
            setPmCoaModalSubtitle(selectedFilterYear ? `Year: ${selectedFilterYear}` : '');
        }

        // Get MFC numbers for the selected section
        const getSectionMfcNumbers = (): Set<string> => {
            const mfcNumbers = new Set<string>();

            if (explicitFormulas && explicitFormulas.length > 0) {
                explicitFormulas.forEach((f: any) => {
                    const masterCardNo = (f.masterFormulaDetails?.masterCardNo || '').trim().toUpperCase();
                    if (masterCardNo) {
                        mfcNumbers.add(masterCardNo);
                    }
                });
                return mfcNumbers;
            }

            let sectionFormulas: any[] = [];
            if (section === 'main') {
                sectionFormulas = formulas.filter((f: any) => {
                    const totalBatchCount = f.totalBatchCount || 0;
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    const isPlacebo = productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                    return totalBatchCount >= 3 && !isPlacebo;
                });
            } else if (section === 'lowBatch') {
                sectionFormulas = formulas.filter((f: any) => {
                    const totalBatchCount = f.totalBatchCount || 0;
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    const isPlacebo = productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                    return totalBatchCount >= 1 && totalBatchCount <= 2 && !isPlacebo;
                });
            } else if (section === 'noBatch') {
                sectionFormulas = formulas.filter((f: any) => {
                    const totalBatchCount = f.totalBatchCount || 0;
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    const isPlacebo = productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                    return totalBatchCount === 0 && !isPlacebo;
                });
            } else if (section === 'placebo') {
                sectionFormulas = formulas.filter((f: any) => {
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    return productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                });
            } else {
                sectionFormulas = formulas;
            }

            sectionFormulas.forEach((f: any) => {
                const masterCardNo = (f.masterFormulaDetails?.masterCardNo || '').trim().toUpperCase();
                if (masterCardNo) {
                    mfcNumbers.add(masterCardNo);
                }
            });

            return mfcNumbers;
        };

        const sectionMfcNumbers = getSectionMfcNumbers();

        // ENHANCEMENT: Build a list of valid product codes for MFC-specific filtering
        // When a single formula is selected, we want to only show data for batches belonging to that MFC
        const validProductCodes = new Set<string>();
        if (explicitFormulas && explicitFormulas.length > 0) {
            explicitFormulas.forEach((formula: any) => {
                const mainCode = formula.masterFormulaDetails?.productCode;
                if (mainCode && mainCode !== 'N/A') validProductCodes.add(mainCode);
                if (formula.fillingDetails && Array.isArray(formula.fillingDetails)) {
                    formula.fillingDetails.forEach((fd: any) => {
                        if (fd.productCode && fd.productCode !== 'N/A') validProductCodes.add(fd.productCode);
                    });
                }
                if (formula.processes && Array.isArray(formula.processes)) {
                    formula.processes.forEach((p: any) => {
                        if (p.fillingProducts && Array.isArray(p.fillingProducts)) {
                            p.fillingProducts.forEach((fp: any) => {
                                if (fp.productCode) validProductCodes.add(fp.productCode);
                            });
                        }
                    });
                }
            });
        }

        try {
            // Same batch scope as dashboard PM COA capsule (pm-verification). Section opens pass mainFormulas[]
            // (many product codes) — must NOT gate on validProductCodes.size===0 or we fall through to Inward logic (~285 rows).
            // Inward Register path only when drilling into a single MFC (one formula).
            const isSingleMfcDrill = (explicitFormulas?.length ?? 0) === 1;
            if (!isSingleMfcDrill) {
                const normBatch = (b: string | null | undefined) => (b || '').toString().trim().toUpperCase();
                const normCode = (c: string | null | undefined) => (c || '').toString().trim().toUpperCase();
                const uniqueBatchToItemCode = new Map<string, string>();
                yearFilteredBatches.forEach((b: any) => {
                    const bn = normBatch(b?.batchNumber);
                    if (!bn || uniqueBatchToItemCode.has(bn)) return;
                    const ic = normCode(b?.itemCode);
                    if (ic) uniqueBatchToItemCode.set(bn, ic);
                });
                const productCodeToSection = buildProductCodeToSectionMap();
                const targetBatches = new Set<string>();
                uniqueBatchToItemCode.forEach((itemCode, bn) => {
                    const cat = productCodeToSection.get((itemCode || '').toString().trim().toUpperCase()) ?? 'main';
                    if (section !== 'all' && cat !== section) return;
                    if (!pmCoaReqFoundBatchNumbers.has(bn)) return;
                    const hasCoa = pmCoaFoundBatchNumbers.has(bn);
                    if (type === 'qualified') {
                        if (hasCoa) targetBatches.add(bn);
                    } else {
                        if (!hasCoa) targetBatches.add(bn);
                    }
                });
                setPmCoaCapsuleBatchCount(targetBatches.size);
                if (targetBatches.size === 0) {
                    setPmCoaModalData([]);
                } else {
                    const requisitionResponse = await fetch('/api/requisition/materials?type=PM&pageSize=100000');
                    const requisitionData = await requisitionResponse.json();
                    if (!requisitionData.success || !Array.isArray(requisitionData.materials)) {
                        setPmCoaModalError(requisitionData.message || 'Failed to fetch PM requisition data');
                    } else {
                        const filteredMaterials = requisitionData.materials
                            .filter((m: any) => {
                                const bn = normBatch(m?.batchNumber);
                                return bn && targetBatches.has(bn);
                            })
                            .map((m: any) => ({
                                arNo: m.arNo || 'N/A',
                                materialCode: m.materialCode || 'N/A',
                                materialName: m.materialName || m.itemName || 'N/A',
                                itemName: m.itemName || 'N/A',
                                batchNumber: normBatch(m.batchNumber) || 'N/A',
                                grNo: m.grNo || 'N/A',
                                formulaMfc: (m.mfcNo || m.formulaMfc || '').toString().trim().toUpperCase() || 'N/A',
                                quantityToIssue: m.quantityToIssue || m.quantityRequired || 0,
                                expiryDate: m.expiryDate || 'N/A',
                                status: type === 'qualified' ? 'PM COA Found' : 'PM COA Missing',
                                sourceFile: 'Requisition',
                            }));
                        setPmCoaModalData(filteredMaterials);
                    }
                }
                return;
            }

            // CRITICAL FIX: Fetch Inward Register AR numbers to properly identify what's actually missing
            const inwardResponse = await fetch('/api/inward/ar-numbers');
            const inwardData = await inwardResponse.json();

            // Build set of AR numbers that exist in Inward Register
            // ENHANCED: Case-insensitive matching + handle version suffixes (.1, .2, etc.)
            // Also fetch Inward Numbers since they can be used as AR Numbers
            const inwardArNumbersSet = new Set<string>();
            if (inwardData.success && inwardData.arNumbers) {
                inwardData.arNumbers.forEach((arNumber: string) => {
                    if (arNumber && arNumber.trim() !== '') {
                        const trimmedAr = arNumber.trim().toUpperCase();
                        // Add the full AR number (uppercase for case-insensitive)
                        inwardArNumbersSet.add(trimmedAr);

                        // Also add the base AR number (without version suffix)
                        // e.g., "IWAAJPM2400231.1" → "IWAAJPM2400231"
                        const baseAr = trimmedAr.split('.')[0];
                        if (baseAr && baseAr !== trimmedAr) {
                            inwardArNumbersSet.add(baseAr);
                        }
                    }
                });
            }

            // ENHANCED: Also fetch Inward Numbers since they're often used as AR numbers
            const inwardNumbersResponse = await fetch('/api/inward/inward-numbers');
            const inwardNumbersData = await inwardNumbersResponse.json();
            if (inwardNumbersData.success && inwardNumbersData.inwardNumbers) {
                inwardNumbersData.inwardNumbers.forEach((inwardNo: string) => {
                    if (inwardNo && inwardNo.trim() !== '') {
                        const trimmedInward = inwardNo.trim().toUpperCase();
                        inwardArNumbersSet.add(trimmedInward);
                        // Also add base without suffix
                        const baseInward = trimmedInward.split('.')[0];
                        if (baseInward && baseInward !== trimmedInward) {
                            inwardArNumbersSet.add(baseInward);
                        }
                    }
                });
            }

            // Build batch to product code mapping for MFC filtering (year-filtered)
            const batchToProductCode = new Map<string, string>();
            if (yearFilteredBatches && yearFilteredBatches.length > 0) {
                yearFilteredBatches.forEach((batch: any) => {
                    if (batch.batchNumber && batch.itemCode) {
                        batchToProductCode.set(batch.batchNumber.trim().toUpperCase(), batch.itemCode);
                    }
                });
            }

            // New Logic: Fetch Requisition data and filter by Inward Qualified Batches
            // This ensures meaningful batch-level display for both Qualified and Unqualified states
            const requisitionResponse = await fetch('/api/requisition/materials?type=PM&pageSize=100000');
            const requisitionData = await requisitionResponse.json();

            if (requisitionData.success && requisitionData.materials) {
                const filteredMaterials: any[] = [];

                // Normalize batch numbers for consistent comparison
                // This handles whitespace and case differences between data sources
                const normalizeBatch = (b: string | null | undefined) => (b || '').trim().toUpperCase();

                // Create System Batches Set from yearFilteredBatches to match Capsule Logic (sectionPmCoaData)
                // The capsule uses yearFilteredBatches for counting, so the modal must use the same source
                const systemBatchesNormalized = new Set<string>();
                yearFilteredBatches.forEach((batch: any) => {
                    if (batch.batchNumber) {
                        const n = normalizeBatch(batch.batchNumber);
                        if (n) systemBatchesNormalized.add(n);
                    }
                });

                // Create normalized lookup Set from backend qualified batches
                const qualifiedBatchesNormalized = new Set<string>();
                pmCoaInwardQualifiedBatchNumbers.forEach(bn => {
                    const normalized = normalizeBatch(bn);
                    // Only include if it is a known system batch
                    if (normalized && systemBatchesNormalized.has(normalized)) {
                        qualifiedBatchesNormalized.add(normalized);
                    }
                });

                // BUILD SECTION BATCH NUMBERS: Pre-compute which batches belong to each section
                // This uses the EXACT same logic as the capsule (sectionPmCoaData) - itemCode → productCodeToCategory
                const sectionBatchNumbers = new Map<'main' | 'lowBatch' | 'noBatch' | 'placebo' | 'all', Set<string>>();
                sectionBatchNumbers.set('main', new Set<string>());
                sectionBatchNumbers.set('lowBatch', new Set<string>());
                sectionBatchNumbers.set('noBatch', new Set<string>());
                sectionBatchNumbers.set('placebo', new Set<string>());
                sectionBatchNumbers.set('all', new Set<string>());

                // Build productCodeToCategory map (same as capsule logic)
                const productCodeToCategory = new Map<string, 'main' | 'lowBatch' | 'noBatch' | 'placebo'>();
                const getFormulaProductCodes = (f: any): string[] => {
                    const codes: string[] = [];
                    const mainCode = f.masterFormulaDetails?.productCode;
                    if (mainCode && mainCode !== 'N/A') codes.push(mainCode);
                    if (f.fillingDetails && Array.isArray(f.fillingDetails)) {
                        f.fillingDetails.forEach((fd: any) => {
                            if (fd.productCode && fd.productCode !== 'N/A' && !codes.includes(fd.productCode)) {
                                codes.push(fd.productCode);
                            }
                        });
                    }
                    if (f.processes && Array.isArray(f.processes)) {
                        f.processes.forEach((p: any) => {
                            if (p.fillingProducts && Array.isArray(p.fillingProducts)) {
                                p.fillingProducts.forEach((fp: any) => {
                                    if (fp.productCode && !codes.includes(fp.productCode)) {
                                        codes.push(fp.productCode);
                                    }
                                });
                            }
                        });
                    }
                    return codes;
                };

                // Separate formulas into categories (same as capsule - uses f.totalBatchCount NOT batchCounts lookup)
                const mainFormulasLocal = formulas.filter((f: any) => {
                    const totalBatchCount = f.totalBatchCount || 0;
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    const isPlacebo = productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                    return totalBatchCount >= 3 && !isPlacebo;
                });
                const lowBatchFormulasLocal = formulas.filter((f: any) => {
                    const totalBatchCount = f.totalBatchCount || 0;
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    const isPlacebo = productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                    return totalBatchCount >= 1 && totalBatchCount <= 2 && !isPlacebo;
                });
                const noBatchFormulasLocal = formulas.filter((f: any) => {
                    const totalBatchCount = f.totalBatchCount || 0;
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    const isPlacebo = productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                    return totalBatchCount === 0 && !isPlacebo;
                });
                const placeboFormulasLocal = formulas.filter((f: any) => {
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    return productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                });

                // Build productCodeToCategory (main first - same priority as capsule)
                mainFormulasLocal.forEach((f: any) => {
                    getFormulaProductCodes(f).forEach(code => {
                        if (!productCodeToCategory.has(code)) productCodeToCategory.set(code, 'main');
                    });
                });
                lowBatchFormulasLocal.forEach((f: any) => {
                    getFormulaProductCodes(f).forEach(code => {
                        if (!productCodeToCategory.has(code)) productCodeToCategory.set(code, 'lowBatch');
                    });
                });
                noBatchFormulasLocal.forEach((f: any) => {
                    getFormulaProductCodes(f).forEach(code => {
                        if (!productCodeToCategory.has(code)) productCodeToCategory.set(code, 'noBatch');
                    });
                });
                placeboFormulasLocal.forEach((f: any) => {
                    getFormulaProductCodes(f).forEach(code => {
                        if (!productCodeToCategory.has(code)) productCodeToCategory.set(code, 'placebo');
                    });
                });

                // For each unique batch in yearFilteredBatches, determine its section and add to sectionBatchNumbers
                // Deduplicate by batchNumber first (keep first record), matching uniqueBatchReconciliation logic
                const seenBatchNumbers = new Set<string>();
                yearFilteredBatches.forEach((batch: any) => {
                    if (!batch.batchNumber) return;
                    const batchNoNorm = normalizeBatch(batch.batchNumber);
                    // Skip if already processed (dedup by batchNumber)
                    if (seenBatchNumbers.has(batchNoNorm)) return;
                    seenBatchNumbers.add(batchNoNorm);

                    const itemCode = batch.itemCode;
                    const category = (itemCode ? productCodeToCategory.get(itemCode) : undefined) || 'main';

                    // Add to the specific section and to 'all'
                    sectionBatchNumbers.get(category)?.add(batchNoNorm);
                    sectionBatchNumbers.get('all')?.add(batchNoNorm);
                });


                // ENHANCED: If filtering by specific MFC, use unique batch logic matching capsule
                if (validProductCodes.size > 0) {
                    // Step 1: Batches for this MFC in the selected year (normalized keys for requisition join)
                    const mfcBatchesNorm = new Set<string>();
                    const pmBatchNormToDisplay = new Map<string, string>();
                    yearFilteredBatches.forEach((batch: any) => {
                        if (batch.batchNumber && batch.itemCode && validProductCodes.has(batch.itemCode)) {
                            const bn = normalizeBatch(batch.batchNumber);
                            if (bn) {
                                mfcBatchesNorm.add(bn);
                                if (!pmBatchNormToDisplay.has(bn)) {
                                    pmBatchNormToDisplay.set(bn, batch.batchNumber);
                                }
                            }
                        }
                    });

                    // Step 2: Find batches that have ANY missing PM COA ARs (same logic as capsule)
                    const batchesWithMissingArsNorm = new Set<string>();
                    requisitionData.materials.forEach((m: any) => {
                        const bn = m.batchNumber ? normalizeBatch(m.batchNumber) : '';
                        if (bn && mfcBatchesNorm.has(bn)) {
                            const arNo = (m.arNo || '').trim();
                            if (arNo) {
                                const arNoUpper = arNo.toUpperCase();
                                const arNoBase = arNoUpper.split('.')[0];
                                // Missing = NOT in Inward Register
                                const isInInward = inwardArNumbersSet.has(arNoUpper) || inwardArNumbersSet.has(arNoBase);
                                if (!isInInward) {
                                    batchesWithMissingArsNorm.add(bn);
                                }
                            }
                        }
                    });

                    // Step 3: Found batches = MFC batches that have NO missing ARs
                    const foundBatchesNorm = new Set<string>();
                    mfcBatchesNorm.forEach(batchNoNorm => {
                        if (!batchesWithMissingArsNorm.has(batchNoNorm)) {
                            foundBatchesNorm.add(batchNoNorm);
                        }
                    });

                    if (type === 'qualified') {
                        // Step 4: Build materials list for found batches with their AR details
                        const batchDataMap = new Map<string, any[]>();

                        requisitionData.materials.forEach((m: any) => {
                            const bn = m.batchNumber ? normalizeBatch(m.batchNumber) : '';
                            if (bn && foundBatchesNorm.has(bn)) {
                                const arNo = (m.arNo || '').trim();
                                if (arNo) {
                                    const arNoUpper = arNo.toUpperCase();
                                    const arNoBase = arNoUpper.split('.')[0];
                                    const isInInward = inwardArNumbersSet.has(arNoUpper) || inwardArNumbersSet.has(arNoBase);
                                    if (isInInward) {
                                        if (!batchDataMap.has(bn)) {
                                            batchDataMap.set(bn, []);
                                        }
                                        batchDataMap.get(bn)!.push(m);
                                    }
                                }
                            }
                        });

                        // Create one record per batch with aggregated AR info
                        foundBatchesNorm.forEach(batchNoNorm => {
                            const batchMaterials = batchDataMap.get(batchNoNorm) || [];
                            const arNumbers = new Set<string>();
                            let materialCode = 'N/A';
                            let materialName = 'Unknown';
                            let formulaMfc = 'N/A';
                            let totalQty = 0;

                            batchMaterials.forEach((m: any) => {
                                if (m.arNo) arNumbers.add(m.arNo.trim());
                                if (m.materialCode && materialCode === 'N/A') materialCode = m.materialCode;
                                if ((m.materialName || m.itemName) && materialName === 'Unknown') {
                                    materialName = m.materialName || m.itemName;
                                }
                                if ((m.mfcNo || m.formulaMfc) && formulaMfc === 'N/A') formulaMfc = (m.mfcNo || m.formulaMfc || '').trim().toUpperCase();
                                totalQty += m.quantityToIssue || m.quantityRequired || 0;
                            });

                            filteredMaterials.push({
                                batchNumber: pmBatchNormToDisplay.get(batchNoNorm) || batchNoNorm,
                                materialCode: materialCode,
                                materialName: materialName,
                                itemName: materialName,
                                arNo: Array.from(arNumbers).join(', '),
                                arCount: arNumbers.size,
                                grNo: 'N/A',
                                formulaMfc: formulaMfc,
                                quantityToIssue: totalQty,
                                expiryDate: 'N/A',
                                status: 'Verified in Inward',
                                sourceFile: 'Inward Register',
                            });
                        });
                    } else {
                        // type === 'unqualified' - show batches with missing ARs
                        const batchDataMap = new Map<string, any[]>();

                        batchesWithMissingArsNorm.forEach(batchNoNorm => {
                            batchDataMap.set(batchNoNorm, []);
                        });

                        requisitionData.materials.forEach((m: any) => {
                            const bn = m.batchNumber ? normalizeBatch(m.batchNumber) : '';
                            if (bn && batchesWithMissingArsNorm.has(bn)) {
                                const arNo = (m.arNo || '').trim();
                                if (arNo) {
                                    const arNoUpper = arNo.toUpperCase();
                                    const arNoBase = arNoUpper.split('.')[0];
                                    const isInInward = inwardArNumbersSet.has(arNoUpper) || inwardArNumbersSet.has(arNoBase);
                                    if (!isInInward) {
                                        batchDataMap.get(bn)!.push(m);
                                    }
                                }
                            }
                        });

                        // Create one record per batch with aggregated missing AR info
                        batchesWithMissingArsNorm.forEach(batchNoNorm => {
                            const batchMaterials = batchDataMap.get(batchNoNorm) || [];
                            const arNumbers = new Set<string>();
                            let materialCode = 'N/A';
                            let materialName = 'Unknown';
                            let formulaMfc = 'N/A';
                            let totalQty = 0;

                            batchMaterials.forEach((m: any) => {
                                if (m.arNo) arNumbers.add(m.arNo.trim());
                                if (m.materialCode && materialCode === 'N/A') materialCode = m.materialCode;
                                if ((m.materialName || m.itemName) && materialName === 'Unknown') {
                                    materialName = m.materialName || m.itemName;
                                }
                                if ((m.mfcNo || m.formulaMfc) && formulaMfc === 'N/A') formulaMfc = (m.mfcNo || m.formulaMfc || '').trim().toUpperCase();
                                totalQty += m.quantityToIssue || m.quantityRequired || 0;
                            });

                            filteredMaterials.push({
                                batchNumber: pmBatchNormToDisplay.get(batchNoNorm) || batchNoNorm,
                                materialCode: materialCode,
                                materialName: materialName,
                                itemName: materialName,
                                arNo: Array.from(arNumbers).join(', '),
                                arCount: arNumbers.size,
                                grNo: 'N/A',
                                formulaMfc: formulaMfc,
                                quantityToIssue: totalQty,
                                expiryDate: 'N/A',
                                status: 'Missing in Inward Register',
                                sourceFile: 'Not Received',
                            });
                        });
                    }
                } else {
                    // Original logic for section-level filtering (no specific MFC)
                    requisitionData.materials.forEach((m: any) => {
                        const mfcNo = (m.mfcNo || m.formulaMfc || '').trim().toUpperCase();
                        const batchNo = m.batchNumber;
                        const batchNoNormalized = normalizeBatch(batchNo);

                        // Filter out batches that are not in the system (Orphans) to match Capsule Count
                        if (!systemBatchesNormalized.has(batchNoNormalized)) return;

                        // Filter by Section using pre-computed sectionBatchNumbers (same logic as capsule)
                        const sectionBatches = sectionBatchNumbers.get(section);
                        if (!sectionBatches || !sectionBatches.has(batchNoNormalized)) return;

                        // Setup Batch Qualification Check using normalized lookup
                        const isQualifiedBatch = qualifiedBatchesNormalized.has(batchNoNormalized);

                        // Filter by Qualification Status
                        if (type === 'qualified') {
                            // Only include materials from Qualified Batches
                            if (isQualifiedBatch) {
                                filteredMaterials.push({
                                    arNo: m.arNo || 'N/A',
                                    materialCode: m.materialCode || 'N/A',
                                    materialName: m.materialName || m.itemName || 'N/A',
                                    itemName: m.itemName || 'N/A',
                                    batchNumber: batchNo || 'N/A',
                                    grNo: m.grNo || 'N/A', // Potentially show if available
                                    formulaMfc: mfcNo || 'N/A',
                                    quantityToIssue: m.quantityToIssue || m.quantityRequired || 0,
                                    expiryDate: m.expiryDate || 'N/A',
                                    status: 'Verified in Inward',
                                    sourceFile: 'Inward Register'
                                });
                            }
                        } else {
                            // Only show AR numbers that are genuinely missing from Inward Register
                            // ENHANCED: Case-insensitive matching + normalize by stripping suffix (e.g., .1, .2)
                            const arTokens = splitArNumbers(m.arNo);
                            arTokens.forEach((arTok) => {
                                const arNoUpper = arTok.toUpperCase();
                                const arNoBase = arNoUpper.split('.')[0];
                                const isArMissingFromInward = arTok && !inwardArNumbersSet.has(arNoUpper) && !inwardArNumbersSet.has(arNoBase);
                                if (batchNo && isArMissingFromInward) {
                                    filteredMaterials.push({
                                        arNo: arTok,
                                        materialCode: m.materialCode || 'N/A',
                                        materialName: m.materialName || m.itemName || 'N/A',
                                        itemName: m.itemName || 'N/A',
                                        batchNumber: batchNo || 'N/A',
                                        grNo: m.grNo || 'N/A',
                                        formulaMfc: mfcNo || 'N/A',
                                        quantityToIssue: m.quantityToIssue || m.quantityRequired || 0,
                                        expiryDate: m.expiryDate || 'N/A',
                                        status: 'Missing in Inward Register',
                                        sourceFile: 'Not Received'
                                    });
                                }
                            });
                        }
                    });
                }

                // RECONCILIATION STEP: Ensure we hit exactly 1282 (or the current backend count)
                // Skip reconciliation when filtering by specific MFC (validProductCodes is set)
                if (type === 'qualified' && validProductCodes.size === 0) {
                    // 1. Track which qualified batches we have already added rows for
                    const addedBatchNumbers = new Set<string>();
                    const normBatch = (b: string | null | undefined) => (b || '').trim().toUpperCase();

                    filteredMaterials.forEach(row => {
                        if (row.batchNumber) {
                            addedBatchNumbers.add(normBatch(row.batchNumber));
                        }
                    });

                    // 2. Iterate the MASTER LIST of qualified batches from backend
                    pmCoaInwardQualifiedBatchNumbers.forEach(qualifiedBatchNo => {
                        const batchNoNorm = normBatch(qualifiedBatchNo);

                        // If this qualified batch was NOT found in the material scan above, it means:
                        // A) It has 0 PM requirements (Vacuously Qualified)
                        // B) It has requirements but for some reason they weren't in the requisition list (unlikely but possible)
                        // In either case, it MUST be shown to match the count.

                        // Ensure we only add System Batches
                        if (batchNoNorm && systemBatchesNormalized.has(batchNoNorm) && !addedBatchNumbers.has(batchNoNorm)) {

                            // Check if this batch belongs to the section using pre-computed sectionBatchNumbers
                            const sectionBatches = sectionBatchNumbers.get(section);
                            if (!sectionBatches || !sectionBatches.has(batchNoNorm)) return;

                            // Get MFC for display purposes
                            let batchMfc = 'Unknown';
                            const batchRecord = yearFilteredBatches.find((b: any) => normBatch(b.batchNumber) === batchNoNorm);
                            if (batchRecord && batchRecord.itemCode) {
                                const formula = formulas.find((f: any) => {
                                    if (f.masterFormulaDetails?.productCode === batchRecord.itemCode) return true;
                                    if (f.fillingDetails?.some((fd: any) => fd.productCode === batchRecord.itemCode)) return true;
                                    if (f.processes?.some((p: any) => p.fillingProducts?.some((fp: any) => fp.productCode === batchRecord.itemCode))) return true;
                                    return false;
                                });
                                if (formula) {
                                    batchMfc = formula.masterFormulaDetails?.masterCardNo || 'Unknown';
                                }
                            }

                            filteredMaterials.push({
                                arNo: 'N/A',
                                materialCode: 'N/A',
                                materialName: 'No PM Required (System Qualified)',
                                itemName: 'No PM Required (System Qualified)',
                                batchNumber: qualifiedBatchNo, // Use original casing
                                grNo: 'N/A',
                                formulaMfc: batchMfc,
                                quantityToIssue: 0,
                                expiryDate: 'N/A',
                                status: 'Qualified (No Requirements)',
                                sourceFile: 'System'
                            });
                            addedBatchNumbers.add(batchNoNorm);
                        }
                    });

                    // SECOND RECONCILIATION: Add batches with NO PM requirements (vacuously qualified)
                    // These batches don't appear in pmCoaInwardQualifiedBatchNumbers but should be counted as qualified
                    // because the capsule logic counts them: if (isQualified || !hasRequirements)
                    yearFilteredBatches.forEach((batch: any) => {
                        const batchNoNorm = normBatch(batch.batchNumber);

                        // Skip if no batch number, already added, or if batch HAS PM requirements
                        if (!batchNoNorm || addedBatchNumbers.has(batchNoNorm)) return;
                        if (pmBatchNumbers.has(batch.batchNumber)) return;

                        // Check section membership using pre-computed sectionBatchNumbers
                        const sectionBatches = sectionBatchNumbers.get(section);
                        if (!sectionBatches || !sectionBatches.has(batchNoNorm)) return;

                        // Get MFC for display purposes
                        const itemCode = batch.itemCode;
                        let batchMfc = 'Unknown';
                        if (itemCode) {
                            const formula = formulas.find((f: any) => {
                                if (f.masterFormulaDetails?.productCode === itemCode) return true;
                                if (f.fillingDetails?.some((fd: any) => fd.productCode === itemCode)) return true;
                                if (f.processes?.some((p: any) => p.fillingProducts?.some((fp: any) => fp.productCode === itemCode))) return true;
                                return false;
                            });
                            if (formula) {
                                batchMfc = (formula.masterFormulaDetails?.masterCardNo || '').trim().toUpperCase() || 'Unknown';
                            }
                        }

                        filteredMaterials.push({
                            arNo: 'N/A',
                            materialCode: 'N/A',
                            materialName: 'No PM Required (Vacuously Qualified)',
                            itemName: 'No PM Required (Vacuously Qualified)',
                            batchNumber: batch.batchNumber,
                            grNo: 'N/A',
                            formulaMfc: batchMfc,
                            quantityToIssue: 0,
                            expiryDate: 'N/A',
                            status: 'Qualified (No Requirements)',
                            sourceFile: 'System'
                        });
                        addedBatchNumbers.add(batchNoNorm);
                    });
                }



                setPmCoaModalData(filteredMaterials);
            } else {
                setPmCoaModalError(requisitionData.message || 'Failed to fetch PM requisition data');
            }
        } catch (error) {
            console.error('Error fetching PM COA data:', error);
            setPmCoaModalError('Failed to fetch data');
        } finally {
            setIsPmCoaModalLoading(false);
        }
    }, [formulas, batchCounts, pmCoaInwardQualifiedBatchNumbers, pmBatchNumbers, yearFilteredBatches, buildProductCodeToSectionMap, pmCoaReqFoundBatchNumbers, pmCoaFoundBatchNumbers]);

    const closePmCoaModal = useCallback(() => {
        setShowPmCoaModal(false);
        setPmCoaModalData([]);
        setPmCoaModalError(null);
        setExpandedPmCoaArNumbers(new Set());
        setExpandedPmCoaBatchNumbers(new Set());
        setPmCoaSearchQuery('');
        setPmCoaSearchField('all');
    }, []);


    // Open PPM COA Modal - show PPM materials with/without PPM COA data
    const openPpmCoaModal = useCallback(async (
        type: 'qualified' | 'unqualified',
        section: 'main' | 'lowBatch' | 'noBatch' | 'placebo' | 'all' = 'all',
        explicitFormulas: any[] = [],
        defaultViewMode: 'ar' | 'table' | 'batch' | 'material' = 'batch'
    ) => {
        setShowPpmCoaModal(true);
        setPpmCoaModalType(type);
        setPpmCoaModalSection(section);
        setIsPpmCoaModalLoading(true);
        setPpmCoaCapsuleBatchCount(0); // Will fall back to recomputed count
        setPpmCoaModalError(null);
        setPpmCoaModalData([]);
        setExpandedPpmCoaArNumbers(new Set());
        setExpandedPpmCoaBatchNumbers(new Set());
        setPpmCoaViewMode(defaultViewMode);
        setPpmCoaModalPrimaryMetric(defaultViewMode === 'ar' ? 'ar' : 'batches');

        // Set subtitle based on context
        const ppmYearSuffix = selectedFilterYear ? ` • Year: ${selectedFilterYear}` : '';
        if (explicitFormulas && explicitFormulas.length === 1) {
            const mfc = explicitFormulas[0].masterFormulaDetails?.masterCardNo || 'Unknown MFC';
            const product = explicitFormulas[0].masterFormulaDetails?.productName || '';
            setPpmCoaModalSubtitle(`Filtered by MFC: ${mfc} - ${product}${ppmYearSuffix}`);
        } else if (section !== 'all') {
            setPpmCoaModalSubtitle(`Filtered by ${section === 'main' ? 'MFCs with 3+ batches' : section === 'lowBatch' ? 'Low Batch MFCs' : section === 'noBatch' ? 'No Batch MFCs' : 'Placebo & Media Fill'}${ppmYearSuffix}`);
        } else {
            setPpmCoaModalSubtitle(selectedFilterYear ? `Year: ${selectedFilterYear}` : '');
        }

        // Get MFC numbers for the selected section
        const getSectionMfcNumbers = (): Set<string> => {
            const mfcNumbers = new Set<string>();

            if (explicitFormulas && explicitFormulas.length > 0) {
                explicitFormulas.forEach((f: any) => {
                    const masterCardNo = (f.masterFormulaDetails?.masterCardNo || '').trim().toUpperCase();
                    if (masterCardNo) {
                        mfcNumbers.add(masterCardNo);
                    }
                });
                return mfcNumbers;
            }

            let sectionFormulas: any[] = [];
            if (section === 'main') {
                sectionFormulas = formulas.filter((f: any) => {
                    const totalBatchCount = f.totalBatchCount || 0;
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    const isPlacebo = productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                    return totalBatchCount >= 3 && !isPlacebo;
                });
            } else if (section === 'lowBatch') {
                sectionFormulas = formulas.filter((f: any) => {
                    const totalBatchCount = f.totalBatchCount || 0;
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    const isPlacebo = productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                    return totalBatchCount >= 1 && totalBatchCount <= 2 && !isPlacebo;
                });
            } else if (section === 'noBatch') {
                sectionFormulas = formulas.filter((f: any) => {
                    const totalBatchCount = f.totalBatchCount || 0;
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    const isPlacebo = productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                    return totalBatchCount === 0 && !isPlacebo;
                });
            } else if (section === 'placebo') {
                sectionFormulas = formulas.filter((f: any) => {
                    const productName = (f.masterFormulaDetails?.productName || '').toUpperCase();
                    return productName.includes('PLACEBO') || productName.includes('MEDIA FILL') || productName.includes('MEDIAFILL');
                });
            } else {
                sectionFormulas = formulas;
            }

            sectionFormulas.forEach((f: any) => {
                const masterCardNo = (f.masterFormulaDetails?.masterCardNo || '').trim().toUpperCase();
                if (masterCardNo) {
                    mfcNumbers.add(masterCardNo);
                }
            });

            return mfcNumbers;
        };

        const sectionMfcNumbers = getSectionMfcNumbers();

        // ENHANCEMENT: Build a list of valid product codes for MFC-specific filtering
        // When a single formula is selected, we want to only show data for batches belonging to that MFC
        const validProductCodes = new Set<string>();
        if (explicitFormulas && explicitFormulas.length > 0) {
            explicitFormulas.forEach((formula: any) => {
                const mainCode = formula.masterFormulaDetails?.productCode;
                if (mainCode && mainCode !== 'N/A') validProductCodes.add(mainCode);
                if (formula.fillingDetails && Array.isArray(formula.fillingDetails)) {
                    formula.fillingDetails.forEach((fd: any) => {
                        if (fd.productCode && fd.productCode !== 'N/A') validProductCodes.add(fd.productCode);
                    });
                }
                if (formula.processes && Array.isArray(formula.processes)) {
                    formula.processes.forEach((p: any) => {
                        if (p.fillingProducts && Array.isArray(p.fillingProducts)) {
                            p.fillingProducts.forEach((fp: any) => {
                                if (fp.productCode) validProductCodes.add(fp.productCode);
                            });
                        }
                    });
                }
            });
        }

        try {
            // IMPORTANT: This modal must match the capsule logic.
            // Capsule uses batch-wise COA status among requisition-found batches:
            // - ppmCoaReqFoundBatchNumbers: requisition-found batches (year-filtered upstream)
            // - ppmCoaFoundBatchNumbers: batches with "PPM COA Found"
            const normBatch = (b: string | null | undefined) => (b || '').toString().trim().toUpperCase();
            const normCode = (c: string | null | undefined) => (c || '').toString().trim().toUpperCase();

            const explicitCodes = new Set<string>(Array.from(validProductCodes).map(normCode).filter(Boolean));

            // Build unique, year-filtered batches with itemCode (first occurrence wins)
            const uniqueBatchToItemCode = new Map<string, string>();
            yearFilteredBatches.forEach((b: any) => {
                const bn = normBatch(b?.batchNumber);
                if (!bn || uniqueBatchToItemCode.has(bn)) return;
                const ic = normCode(b?.itemCode);
                if (ic) uniqueBatchToItemCode.set(bn, ic);
            });

            // Build section membership map using the same product-code classification as the page sections
            const productCodeToSection = buildProductCodeToSectionMap();

            const targetBatches = new Set<string>();
            uniqueBatchToItemCode.forEach((itemCode, bn) => {
                // If viewing a single MFC (explicit formulas), restrict to its product codes
                if (explicitCodes.size > 0 && !explicitCodes.has(itemCode)) return;

                const cat = productCodeToSection.get((itemCode || '').toString().trim().toUpperCase()) ?? 'main';
                if (section !== 'all' && cat !== section) return;

                // Only consider requisition-found batches (COA status is meaningful there)
                if (!ppmCoaReqFoundBatchNumbers.has(bn)) return;

                const hasCoa = ppmCoaFoundBatchNumbers.has(bn);
                if (type === 'qualified') {
                    if (hasCoa) targetBatches.add(bn);
                } else {
                    if (!hasCoa) targetBatches.add(bn);
                }
            });

            setPpmCoaCapsuleBatchCount(targetBatches.size);

            if (targetBatches.size === 0) {
                setPpmCoaModalData([]);
                return;
            }

            // Fetch requisition materials and filter down to target batches
            const requisitionResponse = await fetch('/api/requisition/materials?type=PPM&pageSize=100000');
            const requisitionData = await requisitionResponse.json();

            if (!requisitionData.success || !Array.isArray(requisitionData.materials)) {
                setPpmCoaModalError(requisitionData.message || 'Failed to fetch PPM requisition data');
                return;
            }

            const filteredMaterials = requisitionData.materials
                .filter((m: any) => {
                    const bn = normBatch(m?.batchNumber);
                    return bn && targetBatches.has(bn);
                })
                .map((m: any) => ({
                    arNo: m.arNo || 'N/A',
                    materialCode: m.materialCode || 'N/A',
                    materialName: m.materialName || m.itemName || 'N/A',
                    itemName: m.itemName || 'N/A',
                    batchNumber: normBatch(m.batchNumber) || 'N/A',
                    grNo: m.grNo || 'N/A',
                    formulaMfc: (m.mfcNo || m.formulaMfc || '').toString().trim().toUpperCase() || 'N/A',
                    quantityToIssue: m.quantityToIssue || m.quantityRequired || 0,
                    expiryDate: m.expiryDate || 'N/A',
                    status: type === 'qualified' ? 'PPM COA Found' : 'PPM COA Missing',
                    sourceFile: 'Requisition',
                }));

            setPpmCoaModalData(filteredMaterials);
        } catch (error) {
            console.error('Error fetching PPM COA data:', error);
            setPpmCoaModalError('Failed to fetch data');
        } finally {
            setIsPpmCoaModalLoading(false);
        }
    }, [formulas, yearFilteredBatches, buildProductCodeToSectionMap, ppmCoaReqFoundBatchNumbers, ppmCoaFoundBatchNumbers]);

    const closePpmCoaModal = useCallback(() => {
        setShowPpmCoaModal(false);
        setPpmCoaModalData([]);
        setPpmCoaModalError(null);
        setExpandedPpmCoaArNumbers(new Set());
        setExpandedPpmCoaBatchNumbers(new Set());
        setPpmCoaSearchQuery('');
        setPpmCoaSearchField('all');
    }, []);


    // Bulk COA Modal - Open modal to show AR numbers for matched batches or missing batches for unmatched
    const openBulkCoaModal = useCallback(async (
        type: 'matched' | 'unmatched',
        section: 'main' | 'lowBatch' | 'noBatch' | 'placebo' | 'all' = 'all',
        explicitFormulas: any[] = []
    ) => {
        lastBulkCoaOpenRef.current = { type, section, explicitFormulas };
        setShowBulkCoaModal(true);
        setBulkCoaModalType(type);
        setBulkCoaModalSection(section);
        setIsBulkCoaModalLoading(true);
        setBulkCoaModalError(null);
        setBulkCoaModalData([]);
        setExpandedBulkCoaArNumbers(new Set());
        setExpandedBulkCoaMaterialCodes(new Set());
        setExpandedBulkCoaBatchNumbers(new Set());
        setBulkCoaSearchQuery('');
        setBulkCoaSearchField('all');
        setBulkCoaViewMode('batch');
        setBulkCoaSortColumn('batchNo');

        // Subtitle (same pattern as RM COA modal)
        const bulkYearSuffix = selectedFilterYear ? ` • Year: ${selectedFilterYear}` : '';
        if (explicitFormulas && explicitFormulas.length === 1) {
            const mfc = explicitFormulas[0].masterFormulaDetails?.masterCardNo || 'Unknown MFC';
            const product = explicitFormulas[0].masterFormulaDetails?.productName || '';
            setBulkCoaModalSubtitle(`Filtered by MFC: ${mfc} - ${product}${bulkYearSuffix}`);
        } else if (section !== 'all') {
            setBulkCoaModalSubtitle(`Filtered by ${section === 'main' ? 'MFCs with 3+ Batches' : section === 'lowBatch' ? 'Low Batch MFCs' : section === 'noBatch' ? 'No Batch MFCs' : 'Placebo & Media Fill'}${bulkYearSuffix}`);
        } else {
            setBulkCoaModalSubtitle(selectedFilterYear ? `Year: ${selectedFilterYear}` : '');
        }

        try {
            // Get valid product codes for filtering if not 'all'
            const validProductCodes = new Set<string>();
            const isFiltering = section !== 'all' && explicitFormulas.length > 0;

            if (isFiltering) {
                const getFormulaProductCodes = (f: any): string[] => {
                    const codes: string[] = [];
                    const mainCode = f.masterFormulaDetails?.productCode;
                    if (mainCode && mainCode !== 'N/A') codes.push(mainCode);
                    if (f.fillingDetails && Array.isArray(f.fillingDetails)) {
                        f.fillingDetails.forEach((fd: any) => {
                            if (fd.productCode && fd.productCode !== 'N/A' && !codes.includes(fd.productCode)) {
                                codes.push(fd.productCode);
                            }
                        });
                    }
                    if (f.processes && Array.isArray(f.processes)) {
                        f.processes.forEach((p: any) => {
                            if (p.fillingProducts && Array.isArray(p.fillingProducts)) {
                                p.fillingProducts.forEach((fp: any) => {
                                    if (fp.productCode && !codes.includes(fp.productCode)) {
                                        codes.push(fp.productCode);
                                    }
                                });
                            }
                        });
                    }
                    return codes;
                };

                explicitFormulas.forEach(f => {
                    getFormulaProductCodes(f).forEach(code => validProductCodes.add(code));
                });
            }

            const normBatch = (b: string | null | undefined) => (b || '').toString().trim().toUpperCase();

            const getFormulaProductCodesForBulk = (f: any): string[] => {
                const codes: string[] = [];
                const mainCode = f.masterFormulaDetails?.productCode;
                if (mainCode && mainCode !== 'N/A') codes.push(mainCode);
                if (f.fillingDetails && Array.isArray(f.fillingDetails)) {
                    f.fillingDetails.forEach((fd: any) => {
                        if (fd.productCode && fd.productCode !== 'N/A' && !codes.includes(fd.productCode)) {
                            codes.push(fd.productCode);
                        }
                    });
                }
                if (f.processes && Array.isArray(f.processes)) {
                    f.processes.forEach((p: any) => {
                        if (p.fillingProducts && Array.isArray(p.fillingProducts)) {
                            p.fillingProducts.forEach((fp: any) => {
                                if (fp.productCode && !codes.includes(fp.productCode)) {
                                    codes.push(fp.productCode);
                                }
                            });
                        }
                    });
                }
                return codes;
            };
            const itemCodeToMfc = new Map<string, string>();
            formulas.forEach((f: any) => {
                const mfc = (f.masterFormulaDetails?.masterCardNo || '').trim();
                if (!mfc) return;
                getFormulaProductCodesForBulk(f).forEach((code: string) => {
                    if (!itemCodeToMfc.has(code)) itemCodeToMfc.set(code, mfc);
                });
            });

            // Use the pre-computed bulkCoaQualifiedBatchNumbers set (same as capsule)
            // This ensures modal data matches capsule counts exactly

            // Build valid batch numbers set for this MFC filter (same logic as capsule, year-filtered)
            const validBatchNumbers = new Set<string>();
            if (isFiltering) {
                yearFilteredBatches.forEach((batch: any) => {
                    if (batch.batchNumber && batch.itemCode && validProductCodes.has(batch.itemCode)) {
                        validBatchNumbers.add(batch.batchNumber);
                    }
                });
            }

            if (type === 'matched') {
                // Fetch ALL Bulk COA details for matched batches (no limit)
                const bulkCoaResponse = await fetch('/api/coa?stage=BULK&limit=10000');
                const bulkCoaResult = await bulkCoaResponse.json();

                if (!bulkCoaResult.success) {
                    throw new Error(bulkCoaResult.message || 'Failed to fetch Bulk COA data');
                }

                const bulkCoaRecords = bulkCoaResult.data || [];

                const allBulkCoaByBatch = new Map<string, any[]>();
                bulkCoaRecords
                    .filter((coa: any) => bulkCoaQualifiedBatchNumbers.has(normBatch(coa.batchNumber)))
                    .forEach((coa: any) => {
                        const bn = normBatch(coa.batchNumber);
                        if (!allBulkCoaByBatch.has(bn)) allBulkCoaByBatch.set(bn, []);
                        allBulkCoaByBatch.get(bn)!.push(coa);
                    });

                // One row per unique batch (same dedupe as sectionBulkCoaData / sectionRmData)
                const uniqueBulkModalMap = new Map<string, any>();
                yearFilteredBatches.forEach((batch: any) => {
                    if (batch.batchNumber && !uniqueBulkModalMap.has(batch.batchNumber)) {
                        uniqueBulkModalMap.set(batch.batchNumber, batch);
                    }
                });

                const matchedData: any[] = [];
                let bulkCoaRowId = 0;
                uniqueBulkModalMap.forEach((batch: any) => {
                    if (isFiltering) {
                        if (!batch.itemCode || !validProductCodes.has(batch.itemCode)) return;
                        if (!validBatchNumbers.has(batch.batchNumber)) return;
                    }
                    const bn = normBatch(batch.batchNumber);
                    if (!bn || !bulkCoaQualifiedBatchNumbers.has(bn)) return;

                    const lineItemsRaw = allBulkCoaByBatch.get(bn) || [];
                    const coaLineItems = lineItemsRaw.map((c: any) => ({
                        arNumber: c.bulkData?.arNumber || c.arNo || 'N/A',
                        productCode: c.bulkData?.productCode || c.productCode || 'N/A',
                        productName: c.bulkData?.productName || c.productName || 'N/A',
                        testDate: c.bulkData?.testDate || 'N/A',
                        status: c.bulkData?.status || c.status || 'N/A',
                        manufacturer: c.bulkData?.manufacturer || c.manufacturer || 'N/A',
                    }));
                    const first = lineItemsRaw[0];
                    const ic = (batch.itemCode || '').toString().trim();
                    const mfcVal = (ic && itemCodeToMfc.get(ic)) || 'N/A';
                    matchedData.push({
                        _bulkCoaRowId: bulkCoaRowId++,
                        arNumber: first ? (first.bulkData?.arNumber || first.arNo || 'N/A') : 'N/A',
                        batchNumber: batch.batchNumber,
                        productCode: first ? (first.bulkData?.productCode || first.productCode || 'N/A') : (ic || 'N/A'),
                        productName: first ? (first.bulkData?.productName || first.productName || 'N/A') : (batch.itemName || 'N/A'),
                        testDate: first ? (first.bulkData?.testDate || 'N/A') : 'N/A',
                        status: first ? (first.bulkData?.status || first.status || 'N/A') : 'N/A',
                        manufacturer: first ? (first.bulkData?.manufacturer || first.manufacturer || 'N/A') : 'N/A',
                        itemCode: ic || 'N/A',
                        itemName: batch.itemName || 'N/A',
                        mfc: mfcVal,
                        mfcNo: mfcVal,
                        mfgDate: batch.mfgDate || 'N/A',
                        batchSize: batch.batchSize != null && batch.batchSize !== '' ? String(batch.batchSize) : 'N/A',
                        expiryDate: batch.expiryDate || 'N/A',
                        arCount: coaLineItems.length,
                        coaLineItems,
                    });
                });

                setBulkCoaModalData(matchedData);
            } else {
                const uniqueBulkUnmatchedMap = new Map<string, any>();
                yearFilteredBatches.forEach((batch: any) => {
                    if (batch.batchNumber && !uniqueBulkUnmatchedMap.has(batch.batchNumber)) {
                        uniqueBulkUnmatchedMap.set(batch.batchNumber, batch);
                    }
                });

                const unmatchedData: any[] = [];
                let bulkCoaUnmatchedRowId = 0;
                uniqueBulkUnmatchedMap.forEach((batch: any) => {
                    if (isFiltering) {
                        if (!batch.itemCode || !validProductCodes.has(batch.itemCode)) return;
                    }
                    const bn = normBatch(batch.batchNumber);
                    if (!bn || bulkCoaQualifiedBatchNumbers.has(bn)) return;
                    const ic = (batch.itemCode || '').toString().trim();
                    unmatchedData.push({
                        _bulkCoaRowId: bulkCoaUnmatchedRowId++,
                        batchNumber: batch.batchNumber,
                        itemCode: ic || 'N/A',
                        itemName: batch.itemName || 'N/A',
                        mfgDate: batch.mfgDate || 'N/A',
                        expiryDate: batch.expiryDate || 'N/A',
                        department: batch.department || 'N/A',
                        arNumber: 'Missing Bulk COA',
                        mfc: (ic && itemCodeToMfc.get(ic)) || 'N/A',
                        mfcNo: (ic && itemCodeToMfc.get(ic)) || 'N/A',
                        batchSize: batch.batchSize != null && batch.batchSize !== '' ? String(batch.batchSize) : 'N/A',
                        arCount: 0,
                        coaLineItems: [] as any[],
                    });
                });
                setBulkCoaModalData(unmatchedData);
            }
        } catch (error) {
            console.error('Error fetching Bulk COA data:', error);
            setBulkCoaModalError(error instanceof Error ? error.message : 'Failed to fetch data');
        } finally {
            setIsBulkCoaModalLoading(false);
        }
    }, [yearFilteredBatches, bulkCoaQualifiedBatchNumbers, formulas]);

    const closeBulkCoaModal = useCallback(() => {
        setShowBulkCoaModal(false);
        setBulkCoaModalData([]);
        setBulkCoaModalError(null);
        setBulkCoaModalSection('all');
        setExpandedBulkCoaArNumbers(new Set());
        setExpandedBulkCoaMaterialCodes(new Set());
        setExpandedBulkCoaBatchNumbers(new Set());
        setBulkCoaSearchQuery('');
        setBulkCoaSearchField('all');
    }, []);


    // Finish COA Modal - Open modal to show AR numbers for matched batches or missing batches for unmatched
    const openFinishCoaModal = useCallback(async (
        type: 'matched' | 'unmatched',
        section: 'main' | 'lowBatch' | 'noBatch' | 'placebo' | 'all' = 'all',
        explicitFormulas: any[] = []
    ) => {
        lastFinishCoaOpenRef.current = { type, section, explicitFormulas };
        setShowFinishCoaModal(true);
        setFinishCoaModalType(type);
        setFinishCoaModalSection(section);
        setIsFinishCoaModalLoading(true);
        setFinishCoaModalError(null);
        setFinishCoaModalData([]);
        setExpandedFinishCoaArNumbers(new Set());
        setExpandedFinishCoaMaterialCodes(new Set());
        setExpandedFinishCoaBatchNumbers(new Set());
        setFinishCoaSearchQuery('');
        setFinishCoaSearchField('all');
        setFinishCoaViewMode('batch');
        setFinishCoaSortColumn('batchNo');

        // Set subtitle based on context (badge text — same pattern as PM/PPM COA modals)
        const finishYearSuffix = selectedFilterYear ? ` • Year: ${selectedFilterYear}` : '';
        if (explicitFormulas && explicitFormulas.length === 1) {
            const mfc = explicitFormulas[0].masterFormulaDetails?.masterCardNo || 'Unknown MFC';
            const product = explicitFormulas[0].masterFormulaDetails?.productName || '';
            setFinishCoaModalSubtitle(`Filtered by MFC: ${mfc} - ${product}${finishYearSuffix}`);
        } else if (section !== 'all') {
            setFinishCoaModalSubtitle(`Filtered by ${section === 'main' ? 'MFCs with 3+ Batches' : section === 'lowBatch' ? 'Low Batch MFCs' : section === 'noBatch' ? 'No Batch MFCs' : 'Placebo & Media Fill'}${finishYearSuffix}`);
        } else {
            setFinishCoaModalSubtitle(selectedFilterYear ? `Year: ${selectedFilterYear}` : '');
        }

        try {
            // Get valid product codes for filtering if not 'all'
            const validProductCodes = new Set<string>();
            const isFiltering = section !== 'all' && explicitFormulas.length > 0;

            if (isFiltering) {
                const getFormulaProductCodes = (f: any): string[] => {
                    const codes: string[] = [];
                    const mainCode = f.masterFormulaDetails?.productCode;
                    if (mainCode && mainCode !== 'N/A') codes.push(mainCode);
                    if (f.fillingDetails && Array.isArray(f.fillingDetails)) {
                        f.fillingDetails.forEach((fd: any) => {
                            if (fd.productCode && fd.productCode !== 'N/A' && !codes.includes(fd.productCode)) {
                                codes.push(fd.productCode);
                            }
                        });
                    }
                    if (f.processes && Array.isArray(f.processes)) {
                        f.processes.forEach((p: any) => {
                            if (p.fillingProducts && Array.isArray(p.fillingProducts)) {
                                p.fillingProducts.forEach((fp: any) => {
                                    if (fp.productCode && !codes.includes(fp.productCode)) {
                                        codes.push(fp.productCode);
                                    }
                                });
                            }
                        });
                    }
                    return codes;
                };

                explicitFormulas.forEach(f => {
                    getFormulaProductCodes(f).forEach(code => validProductCodes.add(code));
                });
            }

            const normBatch = (b: string | null | undefined) => (b || '').toString().trim().toUpperCase();

            const getFormulaProductCodesForFinish = (f: any): string[] => {
                const codes: string[] = [];
                const mainCode = f.masterFormulaDetails?.productCode;
                if (mainCode && mainCode !== 'N/A') codes.push(mainCode);
                if (f.fillingDetails && Array.isArray(f.fillingDetails)) {
                    f.fillingDetails.forEach((fd: any) => {
                        if (fd.productCode && fd.productCode !== 'N/A' && !codes.includes(fd.productCode)) {
                            codes.push(fd.productCode);
                        }
                    });
                }
                if (f.processes && Array.isArray(f.processes)) {
                    f.processes.forEach((p: any) => {
                        if (p.fillingProducts && Array.isArray(p.fillingProducts)) {
                            p.fillingProducts.forEach((fp: any) => {
                                if (fp.productCode && !codes.includes(fp.productCode)) {
                                    codes.push(fp.productCode);
                                }
                            });
                        }
                    });
                }
                return codes;
            };
            const itemCodeToMfc = new Map<string, string>();
            formulas.forEach((f: any) => {
                const mfc = (f.masterFormulaDetails?.masterCardNo || '').trim();
                if (!mfc) return;
                getFormulaProductCodesForFinish(f).forEach((code: string) => {
                    if (!itemCodeToMfc.has(code)) itemCodeToMfc.set(code, mfc);
                });
            });

            // Use the pre-computed finishCoaQualifiedBatchNumbers set (same as capsule)
            // This ensures modal data matches capsule counts exactly

            // Build valid batch numbers set for this MFC filter (same logic as capsule, year-filtered)
            const validBatchNumbers = new Set<string>();
            if (isFiltering) {
                yearFilteredBatches.forEach((batch: any) => {
                    if (batch.batchNumber && batch.itemCode && validProductCodes.has(batch.itemCode)) {
                        validBatchNumbers.add(batch.batchNumber);
                    }
                });
            }

            if (type === 'matched') {
                // Fetch ALL Finish COA details for matched batches (no limit)
                const finishCoaResponse = await fetch('/api/coa?stage=FINISH&limit=10000');
                const finishCoaResult = await finishCoaResponse.json();

                if (!finishCoaResult.success) {
                    throw new Error(finishCoaResult.message || 'Failed to fetch Finish COA data');
                }

                const finishCoaRecords = finishCoaResult.data || [];

                const allFinishCoaByBatch = new Map<string, any[]>();
                finishCoaRecords
                    .filter((coa: any) => finishCoaQualifiedBatchNumbers.has(normBatch(coa.batchNumber)))
                    .forEach((coa: any) => {
                        const bn = normBatch(coa.batchNumber);
                        if (!allFinishCoaByBatch.has(bn)) allFinishCoaByBatch.set(bn, []);
                        allFinishCoaByBatch.get(bn)!.push(coa);
                    });

                // One row per year-filtered batch record with Finish COA (same cardinality as sectionFinishCoaData qualified)
                const matchedData: any[] = [];
                let finishCoaRowId = 0;
                yearFilteredBatches.forEach((batch: any) => {
                    if (!batch.batchNumber) return;
                    if (isFiltering) {
                        if (!batch.itemCode || !validProductCodes.has(batch.itemCode)) return;
                        if (!validBatchNumbers.has(batch.batchNumber)) return;
                    }
                    const bn = normBatch(batch.batchNumber);
                    if (!bn || !finishCoaQualifiedBatchNumbers.has(bn)) return;

                    const lineItemsRaw = allFinishCoaByBatch.get(bn) || [];
                    const coaLineItems = lineItemsRaw.map((c: any) => ({
                        arNumber: c.finishData?.arNumber || c.arNo || 'N/A',
                        productCode: c.finishData?.productCode || c.productCode || 'N/A',
                        productName: c.finishData?.productName || c.productName || 'N/A',
                        testDate: c.finishData?.testDate || 'N/A',
                        status: c.finishData?.status || c.status || 'N/A',
                        manufacturer: c.finishData?.manufacturer || c.manufacturer || 'N/A',
                    }));
                    const first = lineItemsRaw[0];
                    const ic = (batch.itemCode || '').toString().trim();
                    const mfcVal = (ic && itemCodeToMfc.get(ic)) || 'N/A';
                    matchedData.push({
                        _finishCoaRowId: finishCoaRowId++,
                        arNumber: first ? (first.finishData?.arNumber || first.arNo || 'N/A') : 'N/A',
                        batchNumber: batch.batchNumber,
                        productCode: first ? (first.finishData?.productCode || first.productCode || 'N/A') : (ic || 'N/A'),
                        productName: first ? (first.finishData?.productName || first.productName || 'N/A') : (batch.itemName || 'N/A'),
                        testDate: first ? (first.finishData?.testDate || 'N/A') : 'N/A',
                        status: first ? (first.finishData?.status || first.status || 'N/A') : 'N/A',
                        manufacturer: first ? (first.finishData?.manufacturer || first.manufacturer || 'N/A') : 'N/A',
                        itemCode: ic || 'N/A',
                        itemName: batch.itemName || 'N/A',
                        mfc: mfcVal,
                        mfcNo: mfcVal,
                        mfgDate: batch.mfgDate || 'N/A',
                        batchSize: batch.batchSize != null && batch.batchSize !== '' ? String(batch.batchSize) : 'N/A',
                        expiryDate: batch.expiryDate || 'N/A',
                        arCount: coaLineItems.length,
                        coaLineItems,
                    });
                });

                setFinishCoaModalData(matchedData);
            } else {
                const unmatchedData: any[] = [];
                let finishCoaUnmatchedRowId = 0;
                yearFilteredBatches.forEach((batch: any) => {
                    if (!batch.batchNumber) return;
                    if (isFiltering) {
                        if (!batch.itemCode || !validProductCodes.has(batch.itemCode)) return;
                    }
                    const bn = normBatch(batch.batchNumber);
                    if (!bn || finishCoaQualifiedBatchNumbers.has(bn)) return;
                    const ic = (batch.itemCode || '').toString().trim();
                    unmatchedData.push({
                        _finishCoaRowId: finishCoaUnmatchedRowId++,
                        batchNumber: batch.batchNumber,
                        itemCode: ic || 'N/A',
                        itemName: batch.itemName || 'N/A',
                        mfgDate: batch.mfgDate || 'N/A',
                        expiryDate: batch.expiryDate || 'N/A',
                        department: batch.department || 'N/A',
                        arNumber: 'Missing Finish COA',
                        mfc: (ic && itemCodeToMfc.get(ic)) || 'N/A',
                        mfcNo: (ic && itemCodeToMfc.get(ic)) || 'N/A',
                        batchSize: batch.batchSize != null && batch.batchSize !== '' ? String(batch.batchSize) : 'N/A',
                        arCount: 0,
                        coaLineItems: [] as any[],
                    });
                });

                setFinishCoaModalData(unmatchedData);
            }
        } catch (error) {
            console.error('Error fetching Finish COA data:', error);
            setFinishCoaModalError(error instanceof Error ? error.message : 'Failed to fetch data');
        } finally {
            setIsFinishCoaModalLoading(false);
        }
    }, [yearFilteredBatches, finishCoaQualifiedBatchNumbers, formulas]);

    const closeFinishCoaModal = useCallback(() => {
        setShowFinishCoaModal(false);
        setFinishCoaModalData([]);
        setFinishCoaModalError(null);
        setFinishCoaModalSection('all');
        setExpandedFinishCoaArNumbers(new Set());
        setExpandedFinishCoaMaterialCodes(new Set());
        setExpandedFinishCoaBatchNumbers(new Set());
        setFinishCoaSearchQuery('');
        setFinishCoaSearchField('all');
    }, []);

    const openRmCoaModal = useCallback(async (
        type: 'matched' | 'unmatched',
        section: 'main' | 'lowBatch' | 'noBatch' | 'placebo' | 'all' = 'all',
        explicitFormulas: any[] = [],
        defaultViewMode: 'ar' | 'uniqueMaterial' | 'material' | 'batch' = 'batch'
    ) => {
        const normBatch = (b: string | null | undefined) => (b || '').trim().toUpperCase();

        setShowRmCoaModal(true);
        setRmCoaModalType(type);
        setRmCoaModalSection(section);
        setRmCoaModalData([]);
        setRmCoaSearchQuery('');
        setRmCoaViewMode(defaultViewMode);
        setExpandedRmCoaBatches(new Set());
        setExpandedRmCoaArNumbers(new Set());

        const yearSuffix = selectedFilterYear ? ` • Year: ${selectedFilterYear}` : '';
        if (explicitFormulas && explicitFormulas.length === 1) {
            const mfc = explicitFormulas[0].masterFormulaDetails?.masterCardNo || 'Unknown MFC';
            const product = explicitFormulas[0].masterFormulaDetails?.productName || '';
            setRmCoaModalSubtitle(`Filtered by MFC: ${mfc} - ${product}${yearSuffix}`);
        } else if (section !== 'all') {
            setRmCoaModalSubtitle(
                `Filtered by ${section === 'main'
                    ? 'MFCs with 3+ batches'
                    : section === 'lowBatch'
                        ? 'MFCs with 1–2 batches'
                        : section === 'noBatch'
                            ? 'MFCs with 0 batches'
                            : 'Placebo & Media Fill'
                }${yearSuffix}`
            );
        } else {
            setRmCoaModalSubtitle(selectedFilterYear ? `Year: ${selectedFilterYear}` : '');
        }

        const isFiltering = section !== 'all' && explicitFormulas && explicitFormulas.length > 0;
        const validProductCodes = new Set<string>();
        const getFormulaProductCodes = (f: any): string[] => {
            const codes: string[] = [];
            const mainCode = f.masterFormulaDetails?.productCode;
            if (mainCode && mainCode !== 'N/A') codes.push(mainCode);
            if (f.fillingDetails && Array.isArray(f.fillingDetails)) {
                f.fillingDetails.forEach((fd: any) => {
                    if (fd.productCode && fd.productCode !== 'N/A' && !codes.includes(fd.productCode)) codes.push(fd.productCode);
                });
            }
            if (f.processes && Array.isArray(f.processes)) {
                f.processes.forEach((p: any) => {
                    if (p.fillingProducts && Array.isArray(p.fillingProducts)) {
                        p.fillingProducts.forEach((fp: any) => {
                            if (fp.productCode && !codes.includes(fp.productCode)) codes.push(fp.productCode);
                        });
                    }
                });
            }
            return codes;
        };

        if (isFiltering) {
            explicitFormulas.forEach(f => getFormulaProductCodes(f).forEach(code => validProductCodes.add(code)));
        }

        // Build allowed batch set for this section using Batch Creation (yearFilteredBatches) and the same category map.
        // This is used to filter API rows so the modal matches the capsule scope exactly.
        const productCodeToSection = buildProductCodeToSectionMap();
        const allowedBatchNorm = new Set<string>();
        yearFilteredBatches.forEach((batch: any) => {
            const bnNorm = normBatch(batch.batchNumber);
            if (!bnNorm) return;
            if (isFiltering) {
                if (batch.itemCode && validProductCodes.has(batch.itemCode)) allowedBatchNorm.add(bnNorm);
                return;
            }
            const itemCode = (batch.itemCode || '').toString().trim().toUpperCase();
            const cat = (itemCode ? productCodeToSection.get(itemCode) : undefined) ?? 'main';
            if (section === 'all' || cat === section) allowedBatchNorm.add(bnNorm);
        });

        // Fetch line-level RM COA verification rows (includes AR No now) and filter by allowed batches.
        const qs = selectedFilterYear ? new URLSearchParams({ year: selectedFilterYear }) : new URLSearchParams({ scope: 'all' });
        const drillQs = new URLSearchParams(qs);
        drillQs.set('drill', type === 'matched' ? 'rm_coa_found' : 'rm_coa_missing');
        const res = await fetch(`/api/requisition/rm-coa-verification?${drillQs.toString()}`);
        const data = await res.json();
        const rowsRaw: any[] = Array.isArray(data?.rows) ? data.rows : [];
        const rows = rowsRaw
            .map(r => ({
                ...r,
                batchNumber: (r?.batchNumber || '').toString(),
                batchNorm: normBatch(r?.batchNumber),
                materialCode: (r?.materialCode || 'N/A').toString(),
                materialName: (r?.materialName || 'N/A').toString(),
                arNo: (r?.arNo || '').toString(),
                matReqNo: (r?.matReqNo || '').toString(),
                coaStatus: (r?.coaStatus || '').toString(),
            }))
            .filter(r => r.batchNorm && allowedBatchNorm.has(r.batchNorm));

        // Capsule consistency: for matched/unmatched, count unique batches in the filtered rows
        const uniqueBatches = new Set(rows.map(r => r.batchNorm));
        setRmCoaCapsuleBatchCount(uniqueBatches.size);
        setRmCoaModalData(rows);
    }, [selectedFilterYear, yearFilteredBatches, rmCoaReqFoundBatchNumbers, rmCoaFoundBatchNumbers, buildProductCodeToSectionMap]);

    const closeRmCoaModal = useCallback(() => {
        setShowRmCoaModal(false);
        setRmCoaModalSection('all');
        setRmCoaModalData([]);
        setRmCoaModalSubtitle('');
        setRmCoaSearchQuery('');
        setRmCoaSearchField('all');
        setExpandedRmCoaBatches(new Set());
        setExpandedRmCoaArNumbers(new Set());
    }, []);

    // Per-Formula RM Modal - Opens modal showing RM data for a specific MFC
    const openPerFormulaRmModal = useCallback(async (
        mfcNo: string,
        productCodes: string[], // Array of all product codes for this formula
        formulaName: string,
        type: 'matched' | 'unmatched'
    ) => {
        setPerFormulaRmModalOpen(true);
        setPerFormulaRmMfc(mfcNo);
        setPerFormulaRmType(type);
        setPerFormulaRmFormulaName(formulaName);
        setPerFormulaRmLoading(true);
        setPerFormulaRmError(null);
        setPerFormulaRmData([]);

        // Create a Set of product codes for efficient lookup
        const productCodeSet = new Set(productCodes.filter(pc => pc && pc !== 'N/A'));

        // Helper to parse year from mfgDate (DD-MM-YY or DD-MM-YYYY format)
        const getBatchYear = (mfgDate: string): string => {
            const parts = (mfgDate || '').split('-');
            if (parts.length === 3) {
                const y = parseInt(parts[2], 10);
                if (!isNaN(y)) return (y < 50 ? 2000 + y : 1900 + y).toString();
            }
            return '';
        };
        const matchesYearFilter = (mfgDate: string) =>
            !selectedFilterYear || getBatchYear(mfgDate) === selectedFilterYear;

        try {
            if (type === 'matched') {
                // Fetch RM materials and filter by batches with any of these product codes
                const response = await fetch('/api/requisition/materials?type=RM&pageSize=100000');
                const data = await response.json();

                if (data.success && data.materials) {
                    // Get batch data to map batchNumber -> itemCode (year-filtered)
                    const batchResponse = await fetch('/api/batch?page=1&limit=10000');
                    const batchData = await batchResponse.json();

                    const batchToItemCode: Record<string, string> = {};
                    if (batchData.success && batchData.data) {
                        batchData.data.forEach((record: any) => {
                            record.batches?.forEach((batch: any) => {
                                if (batch.batchNumber && batch.itemCode && matchesYearFilter(batch.mfgDate)) {
                                    batchToItemCode[batch.batchNumber] = batch.itemCode;
                                }
                            });
                        });
                    }

                    // Filter materials to only those whose batch has one of the product codes
                    const filteredMaterials = data.materials.filter((m: any) => {
                        const itemCode = batchToItemCode[m.batchNumber];
                        return itemCode && productCodeSet.has(itemCode);
                    });

                    setPerFormulaRmData(filteredMaterials);
                } else {
                    setPerFormulaRmError(data.message || 'Failed to fetch RM materials');
                }
            } else {
                // Unmatched: Fetch batches with this product code that don't have RM data
                const batchResponse = await fetch('/api/batch?page=1&limit=10000');
                const batchData = await batchResponse.json();

                const rmResponse = await fetch('/api/requisition/materials?type=RM&pageSize=100000');
                const rmData = await rmResponse.json();

                if (batchData.success && batchData.data) {
                    const batchesWithRm = new Set<string>();
                    if (rmData.success && rmData.materials) {
                        rmData.materials.forEach((m: any) => {
                            if (m.batchNumber) batchesWithRm.add(m.batchNumber);
                        });
                    }

                    const unmatchedBatches: any[] = [];
                    batchData.data.forEach((record: any) => {
                        record.batches?.forEach((batch: any) => {
                            // Only include if this batch has one of the formula's product codes and matches year filter
                            if (batch.itemCode && productCodeSet.has(batch.itemCode) && matchesYearFilter(batch.mfgDate)) {
                                if (!batchesWithRm.has(batch.batchNumber)) {
                                    unmatchedBatches.push({
                                        batchNumber: batch.batchNumber,
                                        itemCode: batch.itemCode,
                                        itemName: batch.itemName,
                                        mfgDate: batch.mfgDate,
                                        expiryDate: batch.expiryDate,
                                        batchSize: batch.batchSize,
                                        department: batch.department,
                                        make: record.companyName || batch.make,
                                    });
                                }
                            }
                        });
                    });

                    setPerFormulaRmData(unmatchedBatches);
                } else {
                    setPerFormulaRmError('Failed to fetch batch data');
                }
            }
        } catch (error) {
            console.error('Error fetching per-formula RM data:', error);
            setPerFormulaRmError('Failed to fetch data');
        } finally {
            setPerFormulaRmLoading(false);
        }
    }, [selectedFilterYear]);

    const closePerFormulaRmModal = useCallback(() => {
        setPerFormulaRmModalOpen(false);
        setPerFormulaRmData([]);
        setPerFormulaRmError(null);
        setPerFormulaRmMfc(null);
    }, []);

